window.receiveProjectSource({"path": "tools/env_sync/cli.py", "lines": ["\"\"\"CLI for detecting and syncing local env files from example templates.\"\"\"", "", "from __future__ import annotations", "", "import argparse", "import os", "import re", "import shutil", "import sys", "import tempfile", "from collections import Counter", "from dataclasses import dataclass", "from pathlib import Path", "from typing import Sequence", "", "_ASSIGNMENT_RE = re.compile(", "    r\"^(?P<indent>\\s*)(?P<comment>#\\s*)?(?:(?P<export>export)\\s+)?\"", "    r\"(?P<key>[A-Za-z_][A-Za-z0-9_]*)\\s*=\\s*(?P<value>.*)$\"", ")", "# Mirrors python-dotenv's own value grammar (dotenv/parser.py). Reimplemented", "# rather than imported: the pre-commit hook and CI run this module under a bare", "# `python3` / `uv run --no-project`, where no third-party package is importable.", "_DOTENV_QUOTED_VALUE_RE: dict[str, re.Pattern[str]] = {", "    \"'\": re.compile(r\"'((?:\\\\'|[^'])*)'\"),", "    '\"': re.compile(r'\"((?:\\\\\"|[^\"])*)\"'),", "}", "# What may follow a closing quote and still leave the value empty: nothing, or a", "# dotenv comment with or without a leading space. See _dotenv_value_is_empty.", "_DOTENV_TRAILING_COMMENT_RE = re.compile(r\"\\s*(?:#.*)?$\")", "_NEAR_SECTION_MARKER_RE = re.compile(r\"^#+\\s*section\\s*:\", re.IGNORECASE)", "_SYNC_MARKER = \"# Added by tools.env_sync\"", "", "# Header --reflow emits above assignments that exist locally but not in the example.", "# Reflow never deletes a key, so they are kept rather than pruned. ``--mirror --prune``", "# removes the *active* ones; a commented local-only assignment is outside prune's reach", "# (extra_keys is built from active entries only) and must be removed by hand.", "_REFLOW_LOCAL_ONLY_HEADER = \"# Local-only keys (no example counterpart)\"", "", "# Keys ignored by drift detection and sync (deployment-only / operator-managed).", "# Add prefixes for whole families (e.g. Datadog ``DD_*``) or exact names below.", "_ENV_SYNC_IGNORE_KEY_PREFIXES: tuple[str, ...] = (\"DD\",)", "_ENV_SYNC_IGNORE_EXACT_KEYS: frozenset[str] = frozenset()", "", "# Local-development-only keys that intentionally have no place in the deploy", "# ``.env.template`` (plaintext local DB URLs, per-developer AWS profile, local", "# Confluence credentials). Exempt from the template-superset and section-alignment", "# checks so the local example can carry them without the deploy template needing to.", "#", "# ``OPENAI_API_KEY`` is the sharpest case: the deploy template holds secret *names*", "# resolved from AWS Secrets Manager, never secret values, so a real per-developer key", "# must never enter it. Its reader is ``src/common/aws/openai_secrets.py``", "# (``_ENV_VAR_NAME``) -- a shared module, so it is a shared local-only key rather than", "# an event-extraction one, even though the example that carries it is per-service.", "_ENV_SYNC_TEMPLATE_LOCAL_ONLY_KEYS: frozenset[str] = frozenset(", "    {", "        \"DB_URL_DATALAKE\",", "        \"DB_URL_ACCELERATE\",", "        \"DB_URL_MASTER\",", "        \"DB_URL_INGEST_LEDGER\",", "        \"DB_URL_INGEST_CONTROL\",", "        \"DB_URL_INGEST_CONTROL_ADMIN\",", "        \"DB_URL_DATALAKE_READER\",", "        \"DB_URL_ACCELERATE_READER\",", "        \"AWS_PROFILE_NAME\",", "        \"CONFLUENCE_USER\",", "        \"CONFLUENCE_API_TOKEN\",", "        \"OPENAI_API_KEY\",", "    }", ")", "", "# The committed deploy template every local example must be a subset of.", "_TEMPLATE_RELATIVE_PATH = \".env.template\"", "", "# Example files under ``env/`` that intentionally map to no .env.template section.", "# Their keys are consumed by local-only tooling and must never enter the deploy", "# template. Everything else the glob finds must resolve to a template section.", "_EXAMPLES_WITHOUT_TEMPLATE_SECTION: frozenset[str] = frozenset(", "    {\"env/.local_data_loads.env.example\"}", ")", "", "# Keep these release names aligned with PioDeployment's datalake chart", "# (helm/datalake/charts/eks-datalake/templates/env-configmap.yaml and services.json).", "SERVICE_RELEASES: tuple[str, ...] = (", "    \"feeds\",", "    \"web-extraction\",", "    \"ai-questionnaire\",", "    \"article-translation\",", "    \"entity-classification\",", "    \"ai-model-tagging\",", "    \"event-extraction\",", "    \"event-synthesis\",", ")", "EXTRA_CONFIGMAP_RELEASES: tuple[str, ...] = (\"qa-report\",)", "JOB_RELEASES: tuple[str, ...] = (", "    \"alembic-migrations\",", "    \"fixtures-script-runner\",", "    \"custom-command-script-runner\",", ")", "CONFIGMAP_RELEASES = SERVICE_RELEASES + EXTRA_CONFIGMAP_RELEASES + JOB_RELEASES", "", "# Sections that intentionally have no local example file: no local process runs", "# these releases (the qa-report CronJob and the migration/script-runner jobs).", "# Every OTHER template section must have one, so a new or misspelled section", "# fails loudly instead of being silently unchecked. Phrased as an exemption on", "# purpose -- a membership test against SERVICE_RELEASES would exempt exactly the", "# unrecognised sections this reconciliation exists to catch.", "_SECTIONS_EXEMPT_FROM_EXAMPLES: frozenset[str] = frozenset(EXTRA_CONFIGMAP_RELEASES + JOB_RELEASES)", "_SECTION_MARKER_PREFIX = \"# section:\"", "", "# Section names become path components in _expected_example_path, so anything a", "# marker can spell has to be constrained before it is joined onto ``env/``. A", "# name like ``../../foo`` would otherwise resolve outside the repository's env", "# directory. analyze_section_validation rejects unrecognised names too, but it", "# runs independently of resolve_section_example_map, so neither gate protects the", "# other -- this keeps the path mapping self-contained.", "_SECTION_NAME_RE = re.compile(r\"^[a-z0-9-]+$\")", "", "# The literal marker name the chart honours as its own first disjunct, so a block", "# under it renders to every release exactly like a pre-marker assignment.", "_SHARED_SECTION_MARKER = \"shared\"", "", "# Sentinel for assignments before the first marker, which the chart routes to every", "# release. The newline makes it unreachable by _section_marker_name, which strips a", "# single str.splitlines() line.", "_PRE_MARKER_SECTION = \"\\n<pre-marker>\"", "", "_EXAMPLE_COVERAGE_CONSEQUENCE = (", "    \"the section-aware example check derives its scope from .env.template's own \"", "    \"markers, so an unmapped section or example file is silently unchecked and the \"", "    \"next key that moves between sections drifts with the gate green\"", ")", "", "_SECTION_ALIGNMENT_CONSEQUENCE = (", "    \"a key in the wrong example file means the environment a developer assembles \"", "    \"locally carries a different variable set than the section-scoped ConfigMap the \"", "    \"deployed service receives, so local behavior stops being a signal for deploy \"", "    \"behavior\"", ")", "", "", "# Canonical queue routing keys (``QUEUE_URL_<Queue.name>``). Matched by prefix", "# rather than by importing ``Queue`` from ``src``: ``tools/`` is off", "# ``pythonpath=[\"src\"]`` and this module runs as a pre-commit hook under a bare", "# ``python3``, so a ``from common.aws.sqs.queue import Queue`` would resolve only", "# when PYTHONPATH happens to be set. Hardcoding the seven names was the other", "# option and would drift silently the next time a queue is added -- the canonical", "# set is open, which is exactly why it gets a prefix test and the closed legacy", "# set below gets an allowlist.", "_CANONICAL_QUEUE_PREFIX = \"QUEUE_URL_\"", "", "# An explicit allowlist, not a substring test. Legacy classification is the one", "# input to a code path that DELETES a key from a developer's sole copy of its", "# value (_plan_source_prunes and the env/.env legacy prune both remove without", "# relocating), so it must name exactly what DAT-7760 removes and nothing else. A", "# ``\"_QUEUE_URL\" in key`` test also swept up any unrelated local key sharing the", "# substring -- a hypothetical ``VENDOR_QUEUE_URL_BACKUP`` in a service file would", "# have been pruned with no relocation and no way back.", "#", "# Five of the seventeen carry ``_QUEUE_URL_`` in the middle rather than at the end", "# (``WEBEX_TARGET_QUEUE_URL_LAYER_ONE``, ``..._LAYER_TWO``,", "# ``..._ARTICLE_TRANSLATION``, ``AIQ_TARGET_QUEUE_URL_LAYER_ONE``,", "# ``..._LAYER_TWO``), which is why an ``endswith(\"_QUEUE_URL\")`` test was never", "# right either. Naming all seventeen sidesteps both failure modes: the set is", "# closed (DAT-7760 removes these and no more will be added), so it cannot drift", "# the way the canonical prefix could.", "_LEGACY_QUEUE_NAMES: frozenset[str] = frozenset(", "    {", "        \"FEEDS_TARGET_QUEUE_URL\",", "        \"WEBEX_SOURCE_QUEUE_URL\",", "        \"WEBEX_TARGET_QUEUE_URL_LAYER_ONE\",", "        \"WEBEX_TARGET_QUEUE_URL_LAYER_TWO\",", "        \"WEBEX_TARGET_QUEUE_URL_ARTICLE_TRANSLATION\",", "        \"ENTITY_SOURCE_QUEUE_URL\",", "        \"ENTITY_TARGET_QUEUE_URL\",", "        \"ENTITY_EVENT_EXTRACTION_QUEUE_URL\",", "        \"EE_SOURCE_QUEUE_URL\",", "        \"EE_TARGET_QUEUE_URL\",", "        \"ESS_SOURCE_QUEUE_URL\",", "        \"AIQ_SOURCE_QUEUE_URL\",", "        \"AIQ_TARGET_QUEUE_URL_LAYER_ONE\",", "        \"AIQ_TARGET_QUEUE_URL_LAYER_TWO\",", "        \"MODEL_TAGGING_SOURCE_QUEUE_URL\",", "        \"ARTICLE_TRANSLATION_SOURCE_QUEUE_URL\",", "        \"ARTICLE_TRANSLATION_AI_QUESTIONNAIRE_TARGET_QUEUE_URL\",", "    }", ")", "", "# Raw assignment texts python-dotenv resolves to the empty string. Both quoted", "# forms are truthy as raw text, so an empty check has to name them; see", "# _dotenv_value_is_empty.", "_DOTENV_EMPTY_VALUES: frozenset[str] = frozenset({\"\", '\"\"', \"''\"})", "", "# Where --migrate-canonical moves values to, and the committed seed whose value", "# counts as \"unconfigured\" rather than as a real value a developer chose.", "_MIGRATION_DESTINATION_PATH = \"env/.env\"", "_MIGRATION_DESTINATION_EXAMPLE_PATH = \"env/.env.example\"", "", "# Header written above the relocated assignments, so a later --reflow has a", "# labelled block to place -- the same role _REFLOW_LOCAL_ONLY_HEADER plays.", "_MIGRATION_HEADER = \"# Canonical queue URLs migrated from per-service env files (DAT-7760)\"", "", "# Appended to a drift report whose extra keys include a canonical queue key.", "# Without it the report's only remedy for an extra key is --mirror/--prune, which", "# deletes the developer's real queue URLs instead of relocating them.", "_MIGRATION_REPORT_HINT = (", "    \"    -> canonical queue URLs belong in env/.env: run \"", "    \"`make env-sync-migrate-canonical` (NOT --mirror/--prune, which deletes these values)\"", ")", "", "", "def _is_canonical_queue_key(key: str) -> bool:", "    \"\"\"Return True when ``key`` is a canonical ``QUEUE_URL_<QUEUE>`` routing key.", "", "    :param key: Env variable name.", "    :type key: str", "    :return: True for the canonical spelling ``QueueResolver`` reads.", "    :rtype: bool", "    \"\"\"", "    return key.startswith(_CANONICAL_QUEUE_PREFIX)", "", "", "def _is_legacy_queue_key(key: str) -> bool:", "    \"\"\"Return True when ``key`` is one of the legacy queue names DAT-7760 removes.", "", "    Membership in :data:`_LEGACY_QUEUE_NAMES`, not a substring test: this predicate", "    gates deletion without relocation, so anything it does not name must survive.", "    See that constant for why an allowlist is the only safe shape here.", "", "    :param key: Env variable name.", "    :type key: str", "    :return: True for one of the seventeen legacy names, False for everything else.", "    :rtype: bool", "    \"\"\"", "    return key in _LEGACY_QUEUE_NAMES", "", "", "def _dotenv_value_is_empty(value: str | None) -> bool:", "    \"\"\"Return True when dotenv would resolve this raw assignment text to ``\"\"``.", "", "    The line parser keeps the value exactly as written, quotes included, so a", "    truthiness test on the raw text reads ``KEY=\"\"`` and ``KEY=''`` as configured", "    while ``python-dotenv`` -- what the application actually loads -- resolves both", "    to the empty string. Migration treats an empty value as unconfigured on both", "    sides, so the raw test would let a quoted-empty source win over a real value", "    and would read a quoted-empty destination as a real conflicting value.", "", "    An empty quoted token also counts when only a dotenv comment follows it:", "    ``KEY=\"\" # note`` and ``KEY=\"\"#note`` both resolve to ``\"\"``. The comment does", "    not need a preceding space, which is why the tail is matched by pattern rather", "    than by splitting on ``\" #\"``. An *unquoted* value is deliberately excluded --", "    ``KEY=  # note`` resolves to the literal ``# note``, not to empty -- so the", "    quoted form is the only one whose trailing comment is discarded.", "", "    Deliberately narrow: it recognises the spellings of *empty* and nothing else.", "    It does not unquote, interpolate, or normalise a real value, because", "    ``--migrate-canonical`` relocates assignment text byte-identical and any", "    reformatting here would leak into that.", "", "    :param value: Raw assignment text to the right of ``=``, or None for a line", "        the parser did not read as an assignment.", "    :type value: str | None", "    :return: True when dotenv resolves the value to the empty string.", "    :rtype: bool", "    \"\"\"", "    if value is None:", "        return True", "    stripped = value.strip()", "    if stripped in _DOTENV_EMPTY_VALUES:", "        return True", "    quoted = _DOTENV_QUOTED_VALUE_RE.get(stripped[:1])", "    if quoted is None:", "        return False", "    match = quoted.match(stripped)", "    if match is None or match.group(1) != \"\":", "        return False", "    return _DOTENV_TRAILING_COMMENT_RE.match(stripped[match.end() :]) is not None", "", "", "def env_sync_key_is_ignored(key: str) -> bool:", "    \"\"\"Return True when ``key`` is excluded from env sync.", "", "    Ignored keys are not compared, appended, pruned, or copied when creating a", "    new local file from a template. Extend matching via", "    ``_ENV_SYNC_IGNORE_KEY_PREFIXES`` or ``_ENV_SYNC_IGNORE_EXACT_KEYS``, or", "    add further checks inside this function if needed.", "    \"\"\"", "    if key in _ENV_SYNC_IGNORE_EXACT_KEYS:", "        return True", "    return any(key.startswith(prefix) for prefix in _ENV_SYNC_IGNORE_KEY_PREFIXES)", "", "", "@dataclass(frozen=True)", "class EnvLine:", "    \"\"\"A parsed line from an env-like file.\"\"\"", "", "    raw: str", "    index: int", "    key: str | None = None", "    value: str | None = None", "    is_assignment: bool = False", "    is_commented_assignment: bool = False", "    section: str = _PRE_MARKER_SECTION", "", "", "@dataclass(frozen=True)", "class ParsedEnvFile:", "    \"\"\"Parsed representation of an env file preserving the original lines.\"\"\"", "", "    path: Path", "    lines: tuple[EnvLine, ...]", "", "    @property", "    def raw_lines(self) -> list[str]:", "        \"\"\"Return the file's raw line content in order.\"\"\"", "        return [line.raw for line in self.lines]", "", "    @property", "    def active_entries(self) -> dict[str, EnvLine]:", "        \"\"\"Return active env assignments keyed by variable name.\"\"\"", "        return {", "            line.key: line for line in self.lines if line.is_assignment and line.key is not None", "        }", "", "    @property", "    def commented_entries(self) -> dict[str, EnvLine]:", "        \"\"\"Return commented-out env assignments keyed by variable name.\"\"\"", "        return {", "            line.key: line", "            for line in self.lines", "            if line.is_commented_assignment and line.key is not None", "        }", "", "    @property", "    def all_entries(self) -> dict[str, EnvLine]:", "        \"\"\"Return active and commented env assignments keyed by variable name.\"\"\"", "        entries: dict[str, EnvLine] = {}", "        for line in self.lines:", "            if (line.is_assignment or line.is_commented_assignment) and line.key is not None:", "                entries[line.key] = line", "        return entries", "", "    @property", "    def active_key_order(self) -> list[str]:", "        \"\"\"Return active env keys in file order.\"\"\"", "        return [line.key for line in self.lines if line.is_assignment and line.key is not None]", "", "", "@dataclass(frozen=True)", "class EnvPair:", "    \"\"\"An example env file and its corresponding local target file.\"\"\"", "", "    example_path: Path", "    local_path: Path", "", "", "@dataclass(frozen=True)", "class PairReport:", "    \"\"\"Drift analysis result for one example/local env pair.\"\"\"", "", "    pair: EnvPair", "    local_exists: bool", "    missing_keys: list[str]", "    extra_keys: list[str]", "    missing_commented_keys: list[str]", "    order_differs: bool", "", "    @property", "    def has_drift(self) -> bool:", "        \"\"\"Return True when the pair has actionable sync drift.\"\"\"", "        return (", "            not self.local_exists", "            or bool(self.missing_keys)", "            or bool(self.extra_keys)", "            or bool(self.missing_commented_keys)", "        )", "", "", "@dataclass(frozen=True)", "class TemplateSupersetReport:", "    \"\"\"Result of checking that one example file is a subset of the template.\"\"\"", "", "    example_path: Path", "    template_path: Path", "    template_exists: bool", "    missing_from_template: list[str]", "", "    @property", "    def has_drift(self) -> bool:", "        \"\"\"Return True when the example carries keys the template lacks.\"\"\"", "        return not self.template_exists or bool(self.missing_from_template)", "", "", "@dataclass(frozen=True)", "class ExampleSectionMisplacement:", "    \"\"\"One example key sitting in a file that does not own its template section.\"\"\"", "", "    key: str", "    example_path: Path", "    example_section: str", "    template_sections: tuple[str, ...]", "", "", "@dataclass(frozen=True)", "class ExampleSectionAlignmentReport:", "    \"\"\"Section-placement drift between the template and every mapped example.\"\"\"", "", "    template_path: Path", "    misplacements: tuple[ExampleSectionMisplacement, ...]", "", "    @property", "    def has_drift(self) -> bool:", "        \"\"\"Return True when any example key sits in the wrong file.\"\"\"", "        return bool(self.misplacements)", "", "", "@dataclass(frozen=True)", "class ReflowResult:", "    \"\"\"Computed reflow output for one pair, with the safety verdict.\"\"\"", "", "    pair: EnvPair", "    reflowed_lines: tuple[str, ...]", "    changed: bool", "    aborted: bool", "    abort_reason: str | None", "    # The exact local content the round-trip guard ran against. Carried so", "    # apply_reflow can confirm the file still holds it before replacing it:", "    # os.replace makes the write atomic, which prevents a torn file but not a", "    # lost update from an editor autosave between compute and apply.", "    original_text: str = \"\"", "", "", "@dataclass(frozen=True)", "class ReleaseRender:", "    \"\"\"Active template keys rendered into one Helm release.\"\"\"", "", "    release: str", "    keys: tuple[str, ...]", "", "", "@dataclass(frozen=True)", "class SectionRenderReport:", "    \"\"\"Simulated ConfigMap renders for every datalake release.\"\"\"", "", "    template_path: Path", "    releases: tuple[ReleaseRender, ...]", "", "", "@dataclass(frozen=True)", "class ReleaseSectionDiff:", "    \"\"\"Added and removed ConfigMap keys for one release.\"\"\"", "", "    release: str", "    removed: tuple[str, ...]", "    added: tuple[str, ...]", "", "", "@dataclass(frozen=True)", "class SectionCompareReport:", "    \"\"\"Per-release ConfigMap key differences between two templates.\"\"\"", "", "    old_template_path: Path", "    new_template_path: Path", "    releases: tuple[ReleaseSectionDiff, ...]", "", "", "@dataclass(frozen=True)", "class SectionValidationViolation:", "    \"\"\"One invalid or unsafe section-routing construct in a template.\"\"\"", "", "    line_number: int", "    message: str", "    source: str", "", "", "@dataclass(frozen=True)", "class SectionValidationReport:", "    \"\"\"Section-marker and DB secret routing validation for one template.\"\"\"", "", "    template_path: Path", "    violations: tuple[SectionValidationViolation, ...]", "", "    @property", "    def has_violations(self) -> bool:", "        \"\"\"Return True when the template is unsafe for section rendering.\"\"\"", "        return bool(self.violations)", "", "", "def _error(message: str) -> None:", "    print(f\"Error: {message}\", file=sys.stderr)", "", "", "def _warn(message: str) -> None:", "    print(f\"Warning: {message}\", file=sys.stderr)", "", "", "def _find_repo_root(start: Path | None = None) -> Path:", "    \"\"\"Resolve the repository root by locating ``pyproject.toml``.\"\"\"", "    current = (start or Path(__file__).resolve()).resolve()", "    for parent in [current, *current.parents]:", "        if (parent / \"pyproject.toml\").exists():", "            return parent", "    raise RuntimeError(\"Could not locate repository root (missing pyproject.toml)\")", "", "", "def _parse_line(raw: str, index: int, section: str = _PRE_MARKER_SECTION) -> EnvLine:", "    \"\"\"Parse a single env file line into assignment metadata when possible.\"\"\"", "    match = _ASSIGNMENT_RE.match(raw)", "    if match is None:", "        return EnvLine(raw=raw, index=index, section=section)", "", "    return EnvLine(", "        raw=raw,", "        index=index,", "        key=match.group(\"key\"),", "        value=match.group(\"value\"),", "        is_assignment=match.group(\"comment\") is None,", "        is_commented_assignment=match.group(\"comment\") is not None,", "        section=section,", "    )", "", "", "def _section_marker_name(raw: str) -> str | None:", "    \"\"\"Return the Helm section name when ``raw`` is an exact marker.", "", "    The datalake chart trims the whole line before checking the prefix, then", "    treats everything after the first colon (trimmed) as the section name.", "    \"\"\"", "    trimmed = raw.strip()", "    if not trimmed.startswith(_SECTION_MARKER_PREFIX):", "        return None", "    return trimmed.split(\":\", maxsplit=1)[1].strip()", "", "", "def _canonical_section(section: str) -> str:", "    \"\"\"Collapse both spellings the chart routes everywhere into one name.", "", "    Pre-marker assignments carry :data:`_PRE_MARKER_SECTION`; an explicit", "    ``# section: shared`` block carries the literal marker name. The chart's", "    first disjunct routes both to every release, so section-aware logic must", "    treat them as the same section.", "", "    :param section: Section name as parsed from a template or example line.", "    :type section: str", "    :return: ``_SHARED_SECTION_MARKER`` for either shared spelling, else the", "        section unchanged.", "    :rtype: str", "    \"\"\"", "    return _SHARED_SECTION_MARKER if section == _PRE_MARKER_SECTION else section", "", "", "def _expected_example_path(section: str) -> str:", "    \"\"\"Return the repo-relative example file that owns a template section.", "", "    The mapping is the naming convention :func:`discover_env_pairs` already", "    relies on: ``env/.{snake_case}.env.example`` pairs with the kebab-case Helm", "    release of the same name, and both shared spellings own the root example.", "", "    :param section: Section name as parsed from a template marker.", "    :type section: str", "    :return: Repository-relative path of the example file owning that section.", "    :rtype: str", "    \"\"\"", "    if _canonical_section(section) == _SHARED_SECTION_MARKER:", "        return \"env/.env.example\"", "    return f\"env/.{section.replace('-', '_')}.env.example\"", "", "", "def _migratable_example_paths() -> dict[str, int]:", "    \"\"\"Return the per-service example paths ``--migrate-canonical`` scopes itself to.", "", "    Derived from :data:`SERVICE_RELEASES` through the same", "    :func:`_expected_example_path` mapping the section checks use, so a new service", "    release is picked up without a second list to keep in sync.", "", "    :return: Repository-relative example path to its index in release order.", "    :rtype: dict[str, int]", "    \"\"\"", "    return {", "        _expected_example_path(release): index for index, release in enumerate(SERVICE_RELEASES)", "    }", "", "", "def _is_migratable_pair(pair: EnvPair, repo_root: Path) -> bool:", "    \"\"\"Return True when ``--migrate-canonical`` reads and prunes this pair's local file.", "", "    Shared by :func:`_migratable_pairs` and the drift report so the report can never", "    recommend the migration for a pair the migration excludes.", "", "    :param pair: The example/local pair to classify.", "    :type pair: EnvPair", "    :param repo_root: Repository root used to render a comparable relative path.", "    :type repo_root: Path", "    :return: True for one of the eight per-service pairs.", "    :rtype: bool", "    \"\"\"", "    return _relative_to_repo(pair.example_path, repo_root) in _migratable_example_paths()", "", "", "def parse_env_file(path: Path) -> ParsedEnvFile:", "    \"\"\"Parse an env-like file while preserving its original line structure.\"\"\"", "    return _parse_env_text(path.read_text(encoding=\"utf-8\"), path)", "", "", "def _parse_env_text(text: str, path: Path) -> ParsedEnvFile:", "    \"\"\"Parse env-like text while preserving its original line structure.", "", "    Split out from :func:`parse_env_file` so text that has been computed but not", "    yet written takes the exact same code path as a file on disk. The reflow", "    round-trip guard depends on that: a parser divergence there would let the", "    guard pass on bytes real parsing would read differently.", "", "    :param text: Full env file content.", "    :type text: str", "    :param path: Path the text belongs to, recorded on the result for reporting.", "    :type path: Path", "    :return: Parsed representation preserving every original line.", "    :rtype: ParsedEnvFile", "    \"\"\"", "    raw_lines = text.splitlines()", "    current_section = _PRE_MARKER_SECTION", "    parsed_lines: list[EnvLine] = []", "    for index, raw in enumerate(raw_lines):", "        marker_name = _section_marker_name(raw)", "        if marker_name is not None:", "            current_section = marker_name", "        parsed_lines.append(_parse_line(raw, index, section=current_section))", "    lines = tuple(parsed_lines)", "    return ParsedEnvFile(path=path, lines=lines)", "", "", "def release_sections(release: str) -> frozenset[str]:", "    \"\"\"Return the template sections the chart renders into one non-job release.", "", "    :param release: A name from :data:`SERVICE_RELEASES` or", "        :data:`EXTRA_CONFIGMAP_RELEASES`.", "    :type release: str", "    :return: Both shared spellings plus the release's own section.", "    :rtype: frozenset[str]", "    \"\"\"", "    # _SHARED_SECTION_MARKER is named alongside the sentinel because the chart's", "    # first disjunct routes an explicit shared marker to every release too.", "    return frozenset({_PRE_MARKER_SECTION, _SHARED_SECTION_MARKER, release})", "", "", "def rendered_keys_by_release(parsed: ParsedEnvFile) -> dict[str, frozenset[str]]:", "    \"\"\"Simulate the chart's section-aware ConfigMap routing by release.\"\"\"", "    active_lines = [line for line in parsed.lines if line.is_assignment and line.key is not None]", "    all_keys = frozenset(line.key for line in active_lines if line.key is not None)", "", "    rendered: dict[str, frozenset[str]] = {}", "    for release in SERVICE_RELEASES + EXTRA_CONFIGMAP_RELEASES:", "        sections = release_sections(release)", "        rendered[release] = frozenset(", "            line.key for line in active_lines if line.key is not None and line.section in sections", "        )", "    for release in JOB_RELEASES:", "        rendered[release] = all_keys", "    return rendered", "", "", "def analyze_section_render(template_path: Path) -> SectionRenderReport:", "    \"\"\"Build a stable, per-release render report for one template.\"\"\"", "    rendered = rendered_keys_by_release(parse_env_file(template_path))", "    return SectionRenderReport(", "        template_path=template_path,", "        releases=tuple(", "            ReleaseRender(release=release, keys=tuple(sorted(rendered[release])))", "            for release in CONFIGMAP_RELEASES", "        ),", "    )", "", "", "def compare_section_renders(", "    old_template_path: Path, new_template_path: Path", ") -> SectionCompareReport:", "    \"\"\"Compare simulated ConfigMap key sets for two templates.\"\"\"", "    old_rendered = rendered_keys_by_release(parse_env_file(old_template_path))", "    new_rendered = rendered_keys_by_release(parse_env_file(new_template_path))", "    return SectionCompareReport(", "        old_template_path=old_template_path,", "        new_template_path=new_template_path,", "        releases=tuple(", "            ReleaseSectionDiff(", "                release=release,", "                removed=tuple(sorted(old_rendered[release] - new_rendered[release])),", "                added=tuple(sorted(new_rendered[release] - old_rendered[release])),", "            )", "            for release in CONFIGMAP_RELEASES", "        ),", "    )", "", "", "def analyze_section_validation(template_path: Path) -> SectionValidationReport:", "    \"\"\"Validate section markers and shared DB secret routing in a template.", "", "    The chart routes on", "    ``or (eq $section \"shared\") (eq $section .Release.Name) $allSections``, so", "    \"shared\" is its own first disjunct: an explicit ``# section: shared`` block", "    renders to every release exactly like a pre-marker assignment. Both shared", "    spellings are therefore accepted here, both satisfy the DB_SECRET_NAME", "    routing invariant, and :func:`rendered_keys_by_release` renders both the", "    same way.", "", "    :param template_path: Template to validate.", "    :type template_path: Path", "    :return: Report listing every marker and DB-secret routing violation found.", "    :rtype: SectionValidationReport", "    \"\"\"", "    parsed = parse_env_file(template_path)", "    violations: list[SectionValidationViolation] = []", "    marker_lines: list[EnvLine] = []", "    known_sections = frozenset(", "        (_SHARED_SECTION_MARKER, *SERVICE_RELEASES, *EXTRA_CONFIGMAP_RELEASES)", "    )", "", "    for line in parsed.lines:", "        trimmed = line.raw.strip()", "        marker_name = _section_marker_name(line.raw)", "        if marker_name is None:", "            if _NEAR_SECTION_MARKER_RE.match(trimmed):", "                violations.append(", "                    SectionValidationViolation(", "                        line_number=line.index + 1,", "                        message=(", "                            \"silently broken section marker; use the exact form \"", "                            \"'# section: <release>'\"", "                        ),", "                        source=line.raw,", "                    )", "                )", "            continue", "", "        marker_lines.append(line)", "        if line.raw != line.raw.lstrip():", "            violations.append(", "                SectionValidationViolation(", "                    line_number=line.index + 1,", "                    message=(", "                        \"section marker works in Helm after trimming but is non-canonical; \"", "                        \"place it at column 0\"", "                    ),", "                    source=line.raw,", "                )", "            )", "        if marker_name not in known_sections:", "            violations.append(", "                SectionValidationViolation(", "                    line_number=line.index + 1,", "                    message=f\"unknown section name '{marker_name}'\",", "                    source=line.raw,", "                )", "            )", "        if any(character.isspace() for character in marker_name):", "            violations.append(", "                SectionValidationViolation(", "                    line_number=line.index + 1,", "                    message=(", "                        \"section name contains whitespace/trailing prose; the renderer treats \"", "                        \"everything after the first ':' as the release name\"", "                    ),", "                    source=line.raw,", "                )", "            )", "", "    db_secret_lines = [", "        line for line in parsed.lines if line.is_assignment and line.key == \"DB_SECRET_NAME\"", "    ]", "    # Preserve legacy marker-free fixture checks that do not model deployment", "    # secrets. Once a template opts into sections (or declares DB_SECRET_NAME),", "    # enforce the PioDeployment parser's exact-one/shared invariant.", "    if marker_lines or db_secret_lines:", "        if len(db_secret_lines) != 1:", "            context_line = db_secret_lines[0] if db_secret_lines else marker_lines[0]", "            violations.append(", "                SectionValidationViolation(", "                    line_number=context_line.index + 1,", "                    message=(", "                        \"DB_SECRET_NAME must have exactly one uncommented assignment; \"", "                        f\"found {len(db_secret_lines)}\"", "                    ),", "                    source=context_line.raw,", "                )", "            )", "        # Both shared spellings are accepted because the chart routes them identically;", "        # rejecting one would recreate a validator/renderer divergence.", "        elif db_secret_lines[0].section not in {_PRE_MARKER_SECTION, _SHARED_SECTION_MARKER}:", "            db_line = db_secret_lines[0]", "            violations.append(", "                SectionValidationViolation(", "                    line_number=db_line.index + 1,", "                    message=\"DB_SECRET_NAME must be in the shared section\",", "                    source=db_line.raw,", "                )", "            )", "", "    return SectionValidationReport(", "        template_path=template_path,", "        violations=tuple(violations),", "    )", "", "", "def discover_env_pairs(repo_root: Path) -> list[EnvPair]:", "    \"\"\"Discover env example/local file pairs supported by the sync tool.\"\"\"", "    pairs: list[EnvPair] = []", "", "    env_dir = repo_root / \"env\"", "    for example_path in sorted(env_dir.glob(\"*.env.example\")):", "        local_name = example_path.name.removesuffix(\".example\")", "        pairs.append(EnvPair(example_path=example_path, local_path=env_dir / local_name))", "", "    local_dev_env = repo_root / \".local\" / \".env\"", "    for example_path in sorted((repo_root / \"tools\").glob(\"*/.env.example\")):", "        pairs.append(EnvPair(example_path=example_path, local_path=local_dev_env))", "", "    return pairs", "", "", "def analyze_pair(pair: EnvPair) -> PairReport:", "    \"\"\"Compute drift between an example env file and its local counterpart.\"\"\"", "    example_file = parse_env_file(pair.example_path)", "    example_active = {", "        k: v for k, v in example_file.active_entries.items() if not env_sync_key_is_ignored(k)", "    }", "    example_commented = {", "        k: v for k, v in example_file.commented_entries.items() if not env_sync_key_is_ignored(k)", "    }", "    example_all_keys = frozenset(example_active) | frozenset(example_commented)", "", "    if not pair.local_path.exists():", "        return PairReport(", "            pair=pair,", "            local_exists=False,", "            missing_keys=list(example_active),", "            extra_keys=[],", "            missing_commented_keys=list(example_commented),", "            order_differs=False,", "        )", "", "    local_file = parse_env_file(pair.local_path)", "    local_active = {", "        k: v for k, v in local_file.active_entries.items() if not env_sync_key_is_ignored(k)", "    }", "    local_all_keys = frozenset(", "        line.key", "        for line in local_file.lines", "        if line.key is not None", "        and not env_sync_key_is_ignored(line.key)", "        and (line.is_assignment or line.is_commented_assignment)", "    )", "", "    missing_keys = [key for key in example_active if key not in local_active]", "    extra_keys = [key for key in local_active if key not in example_all_keys]", "    missing_commented_keys = [key for key in example_commented if key not in local_all_keys]", "", "    common_active_keys = [key for key in example_file.active_key_order if key in local_active]", "    local_common_order = [key for key in local_file.active_key_order if key in example_active]", "    order_differs = common_active_keys != local_common_order", "", "    return PairReport(", "        pair=pair,", "        local_exists=True,", "        missing_keys=missing_keys,", "        extra_keys=extra_keys,", "        missing_commented_keys=missing_commented_keys,", "        order_differs=order_differs,", "    )", "", "", "def _template_relevant_keys(parsed: ParsedEnvFile) -> set[str]:", "    \"\"\"Return active and commented keys not excluded from env sync.\"\"\"", "    return {", "        key", "        for key in parsed.all_entries", "        if not env_sync_key_is_ignored(key) and key not in _ENV_SYNC_TEMPLATE_LOCAL_ONLY_KEYS", "    }", "", "", "def analyze_template_superset(", "    example_path: Path,", "    template_path: Path,", "    parsed_template: ParsedEnvFile | None = None,", ") -> TemplateSupersetReport:", "    \"\"\"Check that an example file's keys are a subset of the deploy template.", "", "    Ignored families (``DD_*``) and the local-only allowlist are excluded from", "    both sides so per-developer values do not register as drift.", "", "    Args:", "        example_path: Path to the local ``.env.example`` file.", "        template_path: Path to the committed deploy ``.env.template`` file.", "        parsed_template: Already-parsed template, supplied by callers checking", "            several examples so the template is read once rather than per file.", "", "    Returns:", "        A report naming any example keys missing from the template.", "    \"\"\"", "    if not template_path.exists() or not example_path.exists():", "        return TemplateSupersetReport(", "            example_path=example_path,", "            template_path=template_path,", "            template_exists=template_path.exists(),", "            missing_from_template=[],", "        )", "", "    if parsed_template is None:", "        parsed_template = parse_env_file(template_path)", "    example_keys = _template_relevant_keys(parse_env_file(example_path))", "    template_keys = _template_relevant_keys(parsed_template)", "    missing = sorted(example_keys - template_keys)", "    return TemplateSupersetReport(", "        example_path=example_path,", "        template_path=template_path,", "        template_exists=True,", "        missing_from_template=missing,", "    )", "", "", "def resolve_section_example_map(", "    repo_root: Path, parsed_template: ParsedEnvFile", ") -> tuple[dict[str, Path], tuple[SectionValidationViolation, ...]]:", "    \"\"\"Map every template section to the example file that must carry its keys.", "", "    The template enumerates the work: sections are discovered from its own", "    markers plus the implicit pre-marker shared region, then resolved outward to", "    expected example paths, so a newly added section is covered automatically.", "    The ``env/*.env.example`` glob is only a completeness cross-check -- an", "    example file can never introduce, rename, or certify a section.", "", "    Both halves of the reconciliation are reported rather than skipped: a", "    section with no example file and an example file with no section are each a", "    named violation, because a silent skip is how a typo'd name drops coverage.", "    ``_SECTIONS_EXEMPT_FROM_EXAMPLES`` only waives the first half -- an exempt", "    section that does have an example file is still mapped and checked.", "", "    :param repo_root: Repository root used to resolve the example paths.", "    :type repo_root: Path", "    :param parsed_template: Already-parsed deploy template.", "    :type parsed_template: ParsedEnvFile", "    :return: Canonical section name to example path for every section that has", "        one, plus one violation per unmapped section and unmapped example file.", "    :rtype: tuple[dict[str, Path], tuple[SectionValidationViolation, ...]]", "    \"\"\"", "    marker_lines: dict[str, EnvLine] = {}", "    for line in parsed_template.lines:", "        marker_name = _section_marker_name(line.raw)", "        if marker_name is not None:", "            marker_lines.setdefault(_canonical_section(marker_name), line)", "", "    # Declared markers and the sections actually carried by lines, so a marker", "    # with no keys under it is still covered.", "    sections = {_canonical_section(line.section) for line in parsed_template.lines}", "    sections.update(marker_lines)", "", "    example_map: dict[str, Path] = {}", "    violations: list[SectionValidationViolation] = []", "    for section in sorted(sections):", "        if not _SECTION_NAME_RE.match(section):", "            marker = marker_lines.get(section)", "            violations.append(", "                SectionValidationViolation(", "                    line_number=marker.index + 1 if marker is not None else 0,", "                    message=(", "                        f\"template section '{section}' is not a valid section name; \"", "                        \"expected lowercase letters, digits and hyphens only\"", "                    ),", "                    source=marker.raw if marker is not None else \"\",", "                )", "            )", "            continue", "        relative = _expected_example_path(section)", "        example_path = repo_root / relative", "        if not example_path.exists():", "            # Exemption means \"no example file is required\", not \"an example file", "            # is exempt from checking\" -- so it only suppresses this violation.", "            if section in _SECTIONS_EXEMPT_FROM_EXAMPLES:", "                continue", "            marker = marker_lines.get(section)", "            violations.append(", "                SectionValidationViolation(", "                    line_number=marker.index + 1 if marker is not None else 0,", "                    message=(", "                        f\"template section '{section}' has no example file; expected {relative}\"", "                    ),", "                    source=marker.raw if marker is not None else \"\",", "                )", "            )", "            continue", "        example_map[section] = example_path", "", "    # Cross-check against the files actually checked, not against every section", "    # name: deriving this from `sections` would let an example file for an exempt", "    # section pass the glob check while never entering example_map, so it would", "    # be silently unchecked -- the exact coverage hole this reconciliation closes.", "    expected_relatives = {_relative_to_repo(path, repo_root) for path in example_map.values()}", "    for example_path in sorted((repo_root / \"env\").glob(\"*.env.example\")):", "        relative = _relative_to_repo(example_path, repo_root)", "        if relative in expected_relatives or relative in _EXAMPLES_WITHOUT_TEMPLATE_SECTION:", "            continue", "        violations.append(", "            SectionValidationViolation(", "                line_number=0,", "                message=(", "                    f\"{relative} maps to no .env.template section; add the section, \"", "                    \"rename the file, or list it in _EXAMPLES_WITHOUT_TEMPLATE_SECTION\"", "                ),", "                source=\"\",", "            )", "        )", "", "    return example_map, tuple(violations)", "", "", "def _derive_template_scope(", "    repo_root: Path, template_path: Path", ") -> tuple[ParsedEnvFile, dict[str, Path], tuple[SectionValidationViolation, ...]]:", "    \"\"\"Parse the template once and resolve the example files it owns.", "", "    Every template-side analysis starts here, so the superset check and the", "    section-alignment check can never disagree about what the template says or", "    which files it routes to.", "", "    :param repo_root: Repository root used to resolve the example paths.", "    :type repo_root: Path", "    :param template_path: Template to read; must exist.", "    :type template_path: Path", "    :return: The parsed template, the section-to-example map, and the", "        section/example reconciliation violations.", "    :rtype: tuple[ParsedEnvFile, dict[str, Path], tuple[SectionValidationViolation, ...]]", "    :raises OSError: If the template cannot be read.", "    \"\"\"", "    parsed_template = parse_env_file(template_path)", "    example_map, violations = resolve_section_example_map(repo_root, parsed_template)", "    return parsed_template, example_map, violations", "", "", "def _template_key_sections(parsed_template: ParsedEnvFile) -> dict[str, frozenset[str]]:", "    \"\"\"Map every actively assigned template key to the sections that route it.", "", "    Active assignments only, matching :func:`rendered_keys_by_release`: a", "    commented template line routes nowhere at deploy time, so it owns no section", "    and cannot make an example placement right or wrong. A key may legitimately", "    appear under several markers (event-synthesis and qa-report share eleven), so", "    the value is a set rather than one name.", "", "    A shared assignment subsumes every other section the same key appears under,", "    so ``shared`` is returned alone whenever present. Membership is what decides", "    placement, and a key routed to every release belongs in the shared example --", "    keeping the specific name in the set would let it satisfy the check from that", "    section's file alone while deploying far wider than that file suggests.", "", "    :param parsed_template: Already-parsed deploy template.", "    :type parsed_template: ParsedEnvFile", "    :return: Key to the canonical section names assigning it.", "    :rtype: dict[str, frozenset[str]]", "    \"\"\"", "    sections: dict[str, set[str]] = {}", "    for line in parsed_template.lines:", "        if not line.is_assignment or line.key is None:", "            continue", "        sections.setdefault(line.key, set()).add(_canonical_section(line.section))", "    return {", "        key: frozenset({_SHARED_SECTION_MARKER})", "        if _SHARED_SECTION_MARKER in names", "        else frozenset(names)", "        for key, names in sections.items()", "    }", "", "", "def analyze_example_section_alignment(", "    repo_root: Path,", "    template_path: Path,", "    scope: tuple[ParsedEnvFile, dict[str, Path], tuple[SectionValidationViolation, ...]]", "    | None = None,", ") -> tuple[ExampleSectionAlignmentReport, tuple[SectionValidationViolation, ...]]:", "    \"\"\"Check that every example key sits in the file owning its template section.", "", "    Placement only -- keys are compared and values never are, because roughly", "    ninety example values intentionally diverge from the template (local", "    overrides, localstack URLs, quoting differences).", "", "    Three cases are deliberately not misplacements: ignored families (``DD_*``),", "    the local-only allowlist, and keys the template does not actively assign at", "    all. The last is the template-superset check's finding, and reporting it here", "    too would double-report a single drift.", "", "    :param repo_root: Repository root used to resolve the example paths.", "    :type repo_root: Path", "    :param template_path: Template whose sections define the expected placement.", "    :type template_path: Path", "    :param scope: Output of :func:`_derive_template_scope`, supplied by callers", "        that already derived it so the template is neither re-read nor re-resolved", "        -- and so both analyses reason about the same derivation.", "    :type scope: tuple[ParsedEnvFile, dict[str, Path], tuple[SectionValidationViolation, ...]] | None", "    :return: The alignment report, plus the section/example reconciliation", "        violations from :func:`resolve_section_example_map`.", "    :rtype: tuple[ExampleSectionAlignmentReport, tuple[SectionValidationViolation, ...]]", "    \"\"\"", "    if scope is None:", "        scope = _derive_template_scope(repo_root, template_path)", "    parsed_template, example_map, violations = scope", "    key_sections = _template_key_sections(parsed_template)", "", "    misplacements: list[ExampleSectionMisplacement] = []", "    for section, example_path in sorted(example_map.items(), key=lambda item: item[1]):", "        parsed_example = parse_env_file(example_path)", "        for key in sorted(parsed_example.active_entries):", "            if env_sync_key_is_ignored(key) or key in _ENV_SYNC_TEMPLATE_LOCAL_ONLY_KEYS:", "                continue", "            template_sections = key_sections.get(key)", "            if template_sections is None or section in template_sections:", "                continue", "            misplacements.append(", "                ExampleSectionMisplacement(", "                    key=key,", "                    example_path=example_path,", "                    example_section=section,", "                    template_sections=tuple(sorted(template_sections)),", "                )", "            )", "", "    return (", "        ExampleSectionAlignmentReport(", "            template_path=template_path, misplacements=tuple(misplacements)", "        ),", "        violations,", "    )", "", "", "def _relative_to_repo(path: Path, repo_root: Path) -> str:", "    \"\"\"Return a display-safe repository-relative path when possible.\"\"\"", "    try:", "        return path.resolve().relative_to(repo_root.resolve()).as_posix()", "    except ValueError:", "        return path.as_posix()", "", "", "def _resolve_selected_pairs(", "    pairs: Sequence[EnvPair],", "    file_arg: str | None,", "    repo_root: Path,", ") -> list[EnvPair]:", "    \"\"\"Filter pairs by a ``--file`` argument targeting either side of a pair.\"\"\"", "    if file_arg is None:", "        return list(pairs)", "", "    normalized = file_arg.replace(\"\\\\\", \"/\")", "    matches: list[EnvPair] = []", "    for pair in pairs:", "        candidates = {", "            pair.local_path.name,", "            pair.example_path.name,", "            _relative_to_repo(pair.local_path, repo_root),", "            _relative_to_repo(pair.example_path, repo_root),", "        }", "        if normalized in candidates:", "            matches.append(pair)", "", "    if not matches:", "        raise ValueError(f\"No env file pair found for: {file_arg}\")", "    if len(matches) > 1:", "        options = \", \".join(", "            f\"{_relative_to_repo(pair.example_path, repo_root)} -> \"", "            f\"{_relative_to_repo(pair.local_path, repo_root)}\"", "            for pair in matches", "        )", "        raise ValueError(f\"Ambiguous --file value '{file_arg}'. Matches: {options}\")", "    return matches", "", "", "def _migration_hint_applies(report: PairReport, repo_root: Path) -> bool:", "    \"\"\"Return True when the drift report should point this pair at the migration.", "", "    Two conditions, both required. The pair has to be one ``--migrate-canonical``", "    actually selects -- ``env/.local_data_loads.env`` and the ``tools/*`` pairs are", "    deliberately outside :func:`_migratable_pairs`, so for them the hint would name", "    a command that cannot relocate the reported value -- and it has to carry a", "    canonical queue key as an extra, which is what makes the generic", "    ``--mirror``/``--prune`` remedy destructive.", "", "    :param report: The pair's drift report.", "    :type report: PairReport", "    :param repo_root: Repository root used to classify the pair.", "    :type repo_root: Path", "    :return: True when the migration hint is actionable for this pair.", "    :rtype: bool", "    \"\"\"", "    if not _is_migratable_pair(report.pair, repo_root):", "        return False", "    return any(_is_canonical_queue_key(key) for key in report.extra_keys)", "", "", "def _render_report(report: PairReport, repo_root: Path) -> list[str]:", "    \"\"\"Render a human-readable drift report for one file pair.\"\"\"", "    pair = report.pair", "    header = (", "        f\"{_relative_to_repo(pair.example_path, repo_root)} -> \"", "        f\"{_relative_to_repo(pair.local_path, repo_root)}\"", "    )", "    status = \"DRIFT\" if report.has_drift else \"OK\"", "    lines = [f\"[{status}] {header}\"]", "", "    if not report.has_drift and not report.order_differs:", "        lines.append(\"  No drift detected.\")", "        return lines", "", "    if not report.local_exists:", "        lines.append(\"  ~ Local file does not exist yet.\")", "", "    if report.missing_keys:", "        lines.append(\"  Missing keys:\")", "        lines.extend(f\"    + {key}\" for key in report.missing_keys)", "", "    if report.extra_keys:", "        lines.append(\"  Extra keys:\")", "        lines.extend(f\"    - {key}\" for key in report.extra_keys)", "        # An extra canonical queue key means the developer's real URL sits in a", "        # per-service file. The generic remedy for an extra key is --mirror/--prune,", "        # which would delete it; point at the relocating command instead (DAT-7760).", "        if _migration_hint_applies(report, repo_root):", "            lines.append(_MIGRATION_REPORT_HINT)", "", "    if report.missing_commented_keys or report.order_differs:", "        lines.append(\"  Template/comment drift:\")", "        if report.missing_commented_keys:", "            lines.extend(", "                f\"    ~ {key} (commented template entry)\" for key in report.missing_commented_keys", "            )", "        if report.order_differs:", "            lines.append(\"    ~ Active key order differs from the example template.\")", "", "    return lines", "", "", "def format_reports(reports: Sequence[PairReport], repo_root: Path) -> str:", "    \"\"\"Format all pair reports for console output.\"\"\"", "    rendered: list[str] = []", "    for index, report in enumerate(reports):", "        if index:", "            rendered.append(\"\")", "        rendered.extend(_render_report(report, repo_root))", "    return \"\\n\".join(rendered)", "", "", "def _render_template_superset_report(report: TemplateSupersetReport, repo_root: Path) -> list[str]:", "    \"\"\"Render the example-is-subset-of-template result for one example file.\"\"\"", "    header = (", "        f\"{_relative_to_repo(report.example_path, repo_root)} \u2286 \"", "        f\"{_relative_to_repo(report.template_path, repo_root)}\"", "    )", "    status = \"DRIFT\" if report.has_drift else \"OK\"", "    lines = [f\"[{status}] {header}\"]", "", "    if not report.template_exists:", "        lines.append(\"  ~ Deploy template not found.\")", "        return lines", "", "    if not report.missing_from_template:", "        lines.append(\"  Example keys are a subset of the template.\")", "        return lines", "", "    lines.append(\"  Example keys missing from the deploy template:\")", "    lines.extend(f\"    + {key}\" for key in report.missing_from_template)", "    return lines", "", "", "def format_template_superset_reports(", "    reports: Sequence[TemplateSupersetReport], repo_root: Path", ") -> str:", "    \"\"\"Format all template-superset reports for console output.\"\"\"", "    rendered: list[str] = []", "    for index, report in enumerate(reports):", "        if index:", "            rendered.append(\"\")", "        rendered.extend(_render_template_superset_report(report, repo_root))", "    return \"\\n\".join(rendered)", "", "", "def format_example_coverage_violations(", "    violations: Sequence[SectionValidationViolation], template_path: Path, repo_root: Path", ") -> str:", "    \"\"\"Format section/example reconciliation violations for console output.", "", "    :param violations: Violations from :func:`resolve_section_example_map`.", "    :type violations: Sequence[SectionValidationViolation]", "    :param template_path: Template the sections were discovered in.", "    :type template_path: Path", "    :param repo_root: Repository root used to shorten displayed paths.", "    :type repo_root: Path", "    :return: The rendered block, or an OK line when nothing is unmapped.", "    :rtype: str", "    \"\"\"", "    display_path = _relative_to_repo(template_path, repo_root)", "    if not violations:", "        return (", "            f\"[OK] example coverage: {display_path}\\n\"", "            \"  Every template section and example file is mapped.\"", "        )", "", "    rendered = [f\"[DRIFT] example coverage: {display_path}\"]", "    for violation in violations:", "        location = f\"{display_path}:{violation.line_number}: \" if violation.line_number else \"\"", "        source = f\": {violation.source.strip()}\" if violation.source.strip() else \"\"", "        rendered.append(f\"  {location}{violation.message}{source}\")", "    rendered.append(f\"  {_EXAMPLE_COVERAGE_CONSEQUENCE}\")", "    return \"\\n\".join(rendered)", "", "", "def format_example_section_alignment_report(", "    report: ExampleSectionAlignmentReport, repo_root: Path", ") -> str:", "    \"\"\"Format section-placement drift, naming key, template section, and file.", "", "    :param report: Alignment report from :func:`analyze_example_section_alignment`.", "    :type report: ExampleSectionAlignmentReport", "    :param repo_root: Repository root used to shorten displayed paths.", "    :type repo_root: Path", "    :return: The rendered block, or an OK line when every key is placed correctly.", "    :rtype: str", "    \"\"\"", "    display_path = _relative_to_repo(report.template_path, repo_root)", "    if not report.has_drift:", "        return (", "            f\"[OK] section alignment: {display_path}\\n\"", "            \"  Every example key sits in the file matching its template section.\"", "        )", "", "    rendered = [", "        f\"[DRIFT] section alignment: {display_path}\",", "        \"  Example keys in the wrong file for their template section:\",", "    ]", "    for misplacement in report.misplacements:", "        routed_to = \", \".join(misplacement.template_sections)", "        rendered.append(f\"    ~ {misplacement.key}: template routes it to {routed_to}\")", "        rendered.append(", "            f\"      but it is active in \"", "            f\"{_relative_to_repo(misplacement.example_path, repo_root)} \"", "            f\"({misplacement.example_section})\"", "        )", "    rendered.append(f\"  {_SECTION_ALIGNMENT_CONSEQUENCE}\")", "    return \"\\n\".join(rendered)", "", "", "def format_section_render_report(report: SectionRenderReport) -> str:", "    \"\"\"Format simulated ConfigMap key sets in stable release/key order.\"\"\"", "    rendered: list[str] = []", "    for index, release in enumerate(report.releases):", "        if index:", "            rendered.append(\"\")", "        rendered.append(f\"[{release.release}]\")", "        rendered.extend(release.keys)", "    return \"\\n\".join(rendered)", "", "", "def format_section_compare_report(report: SectionCompareReport) -> str:", "    \"\"\"Format a stable per-release before/after ConfigMap comparison.\"\"\"", "    rendered: list[str] = []", "    for index, release in enumerate(report.releases):", "        if index:", "            rendered.append(\"\")", "        rendered.append(f\"[{release.release}]\")", "        rendered.append(\"removed:\")", "        rendered.extend(f\"  - {key}\" for key in release.removed)", "        if not release.removed:", "            rendered.append(\"  (none)\")", "        rendered.append(\"added:\")", "        rendered.extend(f\"  + {key}\" for key in release.added)", "        if not release.added:", "            rendered.append(\"  (none)\")", "    return \"\\n\".join(rendered)", "", "", "def format_section_validation_report(report: SectionValidationReport, repo_root: Path) -> str:", "    \"\"\"Format section validation with repository-relative line context.\"\"\"", "    display_path = _relative_to_repo(report.template_path, repo_root)", "    if not report.violations:", "        return f\"[OK] section validation: {display_path}\\n  Section routing is valid.\"", "", "    rendered = [f\"[DRIFT] section validation: {display_path}\"]", "    for violation in report.violations:", "        rendered.append(", "            f\"  {display_path}:{violation.line_number}: {violation.message}: \"", "            f\"{violation.source.strip()}\"", "        )", "    return \"\\n\".join(rendered)", "", "", "def _resolve_template_path(path_arg: str, repo_root: Path) -> Path:", "    \"\"\"Resolve a CLI template path relative to the repository root.\"\"\"", "    path = Path(path_arg)", "    return path if path.is_absolute() else repo_root / path", "", "", "def _append_missing_entries(", "    local_lines: list[str],", "    example_file: ParsedEnvFile,", "    missing_keys: Sequence[str],", "    missing_commented_keys: Sequence[str],", "    example_display_path: str,", ") -> None:", "    \"\"\"Append missing example entries to the local file with sync markers.\"\"\"", "    additions: list[str] = []", "    for key in missing_keys:", "        line = example_file.active_entries[key]", "        additions.append(f\"{_SYNC_MARKER} from {example_display_path}\")", "        additions.append(line.raw)", "", "    for key in missing_commented_keys:", "        line = example_file.commented_entries[key]", "        additions.append(f\"{_SYNC_MARKER} from {example_display_path} (commented template entry)\")", "        additions.append(line.raw)", "", "    if not additions:", "        return", "", "    if local_lines and local_lines[-1].strip():", "        local_lines.append(\"\")", "", "    local_lines.extend(additions)", "", "", "def _prune_extra_keys(local_lines: list[str], extra_keys: Sequence[str]) -> list[str]:", "    \"\"\"Remove active assignment lines for keys that no longer exist in the example.\"\"\"", "    if not extra_keys:", "        return local_lines", "", "    extra_key_set = set(extra_keys)", "    pruned_lines: list[str] = []", "    for index, raw_line in enumerate(local_lines):", "        parsed = _parse_line(raw_line, index)", "        if parsed.is_assignment and parsed.key in extra_key_set:", "            if pruned_lines and pruned_lines[-1].startswith(_SYNC_MARKER):", "                pruned_lines.pop()", "            continue", "", "        pruned_lines.append(raw_line)", "    return pruned_lines", "", "", "def _strip_ignored_assignment_lines(raw_lines: Sequence[str]) -> list[str]:", "    \"\"\"Drop active or commented assignment lines whose keys are ignored.\"\"\"", "    kept: list[str] = []", "    for index, raw in enumerate(raw_lines):", "        parsed = _parse_line(raw, index)", "        if (", "            parsed.key is not None", "            and env_sync_key_is_ignored(parsed.key)", "            and (parsed.is_assignment or parsed.is_commented_assignment)", "        ):", "            continue", "        kept.append(raw)", "    return kept", "", "", "def apply_report(report: PairReport, repo_root: Path, prune: bool) -> list[str]:", "    \"\"\"Apply missing-key sync and optional pruning for a single pair.\"\"\"", "    pair = report.pair", "    actions: list[str] = []", "    local_display = _relative_to_repo(pair.local_path, repo_root)", "    example_display = _relative_to_repo(pair.example_path, repo_root)", "", "    if not report.local_exists:", "        pair.local_path.parent.mkdir(parents=True, exist_ok=True)", "        example_body = pair.example_path.read_text(encoding=\"utf-8\")", "        stripped_lines = _strip_ignored_assignment_lines(example_body.splitlines())", "        out = \"\\n\".join(stripped_lines)", "        if stripped_lines:", "            out += \"\\n\"", "        pair.local_path.write_text(out, encoding=\"utf-8\")", "        actions.append(f\"created {local_display} from {example_display}\")", "        return actions", "", "    example_file = parse_env_file(pair.example_path)", "    local_lines = parse_env_file(pair.local_path).raw_lines", "", "    _append_missing_entries(", "        local_lines,", "        example_file,", "        report.missing_keys,", "        report.missing_commented_keys,", "        example_display,", "    )", "", "    if prune and report.extra_keys:", "        local_lines = _prune_extra_keys(local_lines, report.extra_keys)", "        actions.append(f\"pruned {len(report.extra_keys)} extra key(s) from {local_display}\")", "", "    if report.missing_keys or report.missing_commented_keys:", "        added_count = len(report.missing_keys) + len(report.missing_commented_keys)", "        actions.append(", "            f\"added {added_count} missing template entr{'y' if added_count == 1 else 'ies'} to {local_display}\"", "        )", "", "    output = \"\\n\".join(local_lines)", "    if local_lines:", "        output += \"\\n\"", "    pair.local_path.write_text(output, encoding=\"utf-8\")", "    return actions", "", "", "def reflowable_pairs(pairs: Sequence[EnvPair], repo_root: Path) -> list[EnvPair]:", "    \"\"\"Keep only the pairs :option:`--reflow` is allowed to rewrite.", "", "    ``discover_env_pairs`` also globs ``tools/*/.env.example``, all of which pair", "    to ``.local/.env`` -- a hand-managed file holding a real API key rather than a", "    synced local env file. Restricting reflow to examples sitting directly under", "    ``<repo_root>/env`` excludes those by construction instead of by an allowlist", "    that could rot as new ``tools/`` examples appear.", "", "    :param pairs: Discovered example/local pairs.", "    :type pairs: Sequence[EnvPair]", "    :param repo_root: Repository root owning the ``env/`` directory.", "    :type repo_root: Path", "    :return: The subset of pairs whose example lives directly under ``env/``.", "    :rtype: list[EnvPair]", "    \"\"\"", "    env_dir = (repo_root / \"env\").resolve()", "    return [pair for pair in pairs if pair.example_path.resolve().parent == env_dir]", "", "", "def _assignment_multiset(parsed: ParsedEnvFile) -> Counter[tuple[str, str, str]]:", "    \"\"\"Count a file's assignments with multiplicity, keyed by kind, name and value.", "", "    Deliberately built from ``parsed.lines`` rather than from ``active_entries`` /", "    ``commented_entries`` / ``all_entries``: those are last-wins dict properties, so", "    a file assigning the same key twice collapses to one entry and a dropped", "    assignment would compare equal to the original.", "", "    :param parsed: Parsed env file to summarise.", "    :type parsed: ParsedEnvFile", "    :return: Counter over ``(kind, key, value)`` where kind is active or commented.", "    :rtype: Counter[tuple[str, str, str]]", "    \"\"\"", "    counts: Counter[tuple[str, str, str]] = Counter()", "    for line in parsed.lines:", "        if line.key is None:", "            continue", "        if line.is_assignment:", "            counts[(\"active\", line.key, line.value or \"\")] += 1", "        elif line.is_commented_assignment:", "            counts[(\"commented\", line.key, line.value or \"\")] += 1", "    return counts", "", "", "def _reflow_abort_reason(original: ParsedEnvFile, candidate: ParsedEnvFile) -> str | None:", "    \"\"\"Compare two parsed files' assignments and describe any difference by key.", "", "    Values are never included in the returned text: local env files hold real", "    credentials and this message reaches a terminal or CI log.", "", "    :param original: The file as it exists on disk today.", "    :type original: ParsedEnvFile", "    :param candidate: The computed output, parsed back.", "    :type candidate: ParsedEnvFile", "    :return: A reason naming the affected keys, or None when the two match exactly.", "    :rtype: str | None", "    \"\"\"", "    before = _assignment_multiset(original)", "    after = _assignment_multiset(candidate)", "    if before == after:", "        return None", "", "    lost_keys = {key for _kind, key, _value in (before - after)}", "    gained_keys = {key for _kind, key, _value in (after - before)}", "    parts: list[str] = []", "    if changed := sorted(lost_keys & gained_keys):", "        parts.append(f\"value or comment state changed for {', '.join(changed)}\")", "    if lost := sorted(lost_keys - gained_keys):", "        parts.append(f\"assignment lost for {', '.join(lost)}\")", "    if gained := sorted(gained_keys - lost_keys):", "        parts.append(f\"assignment gained for {', '.join(gained)}\")", "    return f\"round-trip check failed ({'; '.join(parts)}); nothing was written\"", "", "", "def _duplicate_active_keys(parsed: ParsedEnvFile) -> list[str]:", "    \"\"\"Return keys assigned more than once as active lines, in sorted order.\"\"\"", "    counts = Counter(line.key for line in parsed.lines if line.is_assignment and line.key)", "    return sorted(key for key, count in counts.items() if key is not None and count > 1)", "", "", "def _unparsed_line_numbers(parsed: ParsedEnvFile) -> list[int]:", "    \"\"\"Return 1-based numbers of nonblank lines that are neither comment nor assignment.", "", "    :param parsed: Parsed env file to inspect.", "    :type parsed: ParsedEnvFile", "    :return: Line numbers the line-oriented parser does not recognise, in file order.", "    :rtype: list[int]", "    \"\"\"", "    return [", "        line.index + 1", "        for line in parsed.lines", "        if not line.is_assignment", "        and not line.is_commented_assignment", "        and line.raw.strip()", "        and not line.raw.lstrip().startswith(\"#\")", "    ]", "", "", "def _quoted_value_span(text: str, value_at: int) -> re.Match[str] | None:", "    \"\"\"Match a quoted value at ``value_at`` the way dotenv's own parser would.", "", "    :param text: The whole file, since where a quote closes depends on later lines.", "    :type text: str", "    :param value_at: Offset of the value's opening quote.", "    :type value_at: int", "    :return: The match covering the quoted value, or None when nothing closes it.", "    :rtype: re.Match[str] | None", "    \"\"\"", "    pattern = _DOTENV_QUOTED_VALUE_RE.get(text[value_at : value_at + 1])", "    return None if pattern is None else pattern.match(text, value_at)", "", "", "def _unterminated_quote_line_numbers(parsed: ParsedEnvFile) -> list[int]:", "    \"\"\"Return 1-based numbers of assignment lines whose quoted value leaves its line.", "", "    Detected from the assignment that opens the quote rather than from its", "    continuations, because a continuation beginning with ``#`` parses as an", "    ordinary comment and so is invisible to :func:`_unparsed_line_numbers`. Reflow", "    drops every local comment and the round-trip guard compares the same truncated", "    assignment on both sides, so nothing downstream can catch it.", "", "    Matched against the whole file rather than the one line: a backslash lets the", "    grammar cross a quote, and the engine prefers the longest body, so whether", "    ``KEY=\"a\\\\\"`` closes on its own line depends on whether a later quote exists", "    for it to reach. Only dotenv's own patterns settle that.", "", "    :param parsed: Parsed env file to inspect.", "    :type parsed: ParsedEnvFile", "    :return: Line numbers whose value is unterminated or spans lines, in file order.", "    :rtype: list[int]", "    \"\"\"", "    raws = [line.raw for line in parsed.lines]", "    text = \"\\n\".join(raws)", "    line_starts: list[int] = []", "    offset = 0", "    for raw in raws:", "        line_starts.append(offset)", "        offset += len(raw) + 1", "", "    numbers: list[int] = []", "    for line in parsed.lines:", "        if not (line.is_assignment or line.is_commented_assignment):", "            continue", "        match = _ASSIGNMENT_RE.match(line.raw)", "        if match is None:", "            continue", "        value_at = line_starts[line.index] + match.start(\"value\")", "        if text[value_at : value_at + 1] not in (\"'\", '\"'):", "            continue", "        span = _quoted_value_span(text, value_at)", "        if span is None or \"\\n\" in span.group(0):", "            numbers.append(line.index + 1)", "    return numbers", "", "", "def _unparsed_line_abort_reason(parsed: ParsedEnvFile, subject: str) -> str | None:", "    \"\"\"Describe unrecognised lines by number, or return None when every line parses.", "", "    The overwhelmingly likely cause is a multiline quoted value, which the whole", "    module reads as one assignment plus orphan continuation lines. Line numbers", "    only: the message reaches a terminal or CI log and the line itself may be the", "    middle of a private key.", "", "    :param parsed: Parsed env file to inspect.", "    :type parsed: ParsedEnvFile", "    :param subject: How to name the file in the message (empty for the local file,", "        which the caller already prefixes with its path).", "    :type subject: str", "    :return: A reason naming the offending line numbers, or None.", "    :rtype: str | None", "    \"\"\"", "    numbers = sorted(", "        set(_unparsed_line_numbers(parsed)) | set(_unterminated_quote_line_numbers(parsed))", "    )", "    if not numbers:", "        return None", "    where = f\" in {subject}\" if subject else \"\"", "    plural = \"line\" if len(numbers) == 1 else \"lines\"", "    return (", "        f\"unrecognized syntax{where} at {plural} \"", "        f\"{', '.join(str(number) for number in numbers)}; a multiline quoted value \"", "        \"cannot be reordered without losing its continuation lines. Collapse it onto \"", "        \"one line before reflowing; nothing was written\"", "    )", "", "", "def _interpolating_active_keys(parsed: ParsedEnvFile) -> list[str]:", "    \"\"\"Return active keys whose value references another variable, in file order.", "", "    python-dotenv resolves ``${NAME}`` against the values already parsed above the", "    referencing line, so ``DERIVED=${BASE}`` above ``BASE=old`` resolves to the", "    empty string while the same two lines in the other order resolve to ``old``.", "    The reflow round-trip guard compares raw assignments, which are unchanged by a", "    move, so this is a blind spot the guard cannot close after the fact -- the same", "    reason the multiline-quote and duplicate-key refusals are pre-checks.", "", "    :param parsed: The local file as it exists on disk.", "    :type parsed: ParsedEnvFile", "    :return: Referencing keys in file order, empty when none interpolate.", "    :rtype: list[str]", "    \"\"\"", "    return [", "        line.key", "        for line in parsed.lines", "        if line.is_assignment and line.key is not None and \"${\" in (line.value or \"\")", "    ]", "", "", "def _reflow_refusal_reason(", "    local: ParsedEnvFile, example: ParsedEnvFile, example_name: str", ") -> str | None:", "    \"\"\"Describe why a pair cannot be reordered safely, or None when it can.", "", "    Both refusals precede the round-trip guard because neither is something the", "    guard can catch after the fact -- see :func:`compute_reflow` for why.", "", "    :param local: The local file as it exists on disk.", "    :type local: ParsedEnvFile", "    :param example: The example file driving the new order.", "    :type example: ParsedEnvFile", "    :param example_name: Example filename, used to say which file is at fault.", "    :type example_name: str", "    :return: A reason naming lines or keys, never a value, or None.", "    :rtype: str | None", "    \"\"\"", "    for parsed, subject in ((local, \"\"), (example, example_name)):", "        if reason := _unparsed_line_abort_reason(parsed, subject):", "            return reason", "", "    if duplicates := _duplicate_active_keys(local):", "        return (", "            f\"duplicate active assignments for {', '.join(duplicates)}; dotenv \"", "            \"resolution is last-wins, so reordering would change the effective \"", "            \"value. Remove the redundant assignments by hand before reflowing \"", "            \"(--mirror --prune only drops keys the example does not carry at all, \"", "            \"so it will not deduplicate a key the example owns)\"", "        )", "", "    if interpolating := _interpolating_active_keys(local):", "        return (", "            f\"active assignments referencing another variable: \"", "            f\"{', '.join(interpolating)}; dotenv resolves ${{NAME}} against the keys \"", "            \"defined ABOVE it, so moving a reference across its referent silently \"", "            \"changes the resolved value while every raw line stays byte-identical. \"", "            \"Inline the referenced value before reflowing; nothing was written\"", "        )", "    return None", "", "", "def _reflow_lines(local: ParsedEnvFile, example: ParsedEnvFile) -> list[str]:", "    \"\"\"Rebuild the local file's lines in the example's order and comment structure.", "", "    Every assignment emitted is the local file's own ``raw`` line, moved rather", "    than rebuilt. Local assignments the example does not carry are appended under", "    :data:`_REFLOW_LOCAL_ONLY_HEADER` rather than dropped.", "", "    :param local: The local file as it exists on disk.", "    :type local: ParsedEnvFile", "    :param example: The example file driving the new order.", "    :type example: ParsedEnvFile", "    :return: The reordered lines, without a trailing newline.", "    :rtype: list[str]", "    \"\"\"", "    pending: dict[tuple[str, str], list[EnvLine]] = {}", "    for line in local.lines:", "        if line.key is None:", "            continue", "        if line.is_assignment:", "            pending.setdefault((\"active\", line.key), []).append(line)", "        elif line.is_commented_assignment:", "            pending.setdefault((\"commented\", line.key), []).append(line)", "", "    consumed: set[int] = set()", "", "    def _take(key: str) -> EnvLine | None:", "        \"\"\"Pop the next unplaced local line for a key, preferring the active one.\"\"\"", "        for kind in (\"active\", \"commented\"):", "            candidates = pending.get((kind, key))", "            if candidates:", "                taken = candidates.pop(0)", "                consumed.add(taken.index)", "                return taken", "        return None", "", "    reflowed: list[str] = []", "    # A comment block sitting directly above an assignment documents that assignment,", "    # so it is held back and dropped with the assignment when the key has no local", "    # counterpart -- otherwise it would reattach to whichever key follows and describe", "    # the wrong variable. A blank line ends the block, so section headers still survive.", "    held_comments: list[str] = []", "    for line in example.lines:", "        if line.is_assignment or line.is_commented_assignment:", "            if line.key is not None and (local_line := _take(line.key)) is not None:", "                reflowed.extend(held_comments)", "                reflowed.append(local_line.raw)", "            held_comments.clear()", "            continue", "        if line.raw.startswith(_SYNC_MARKER):", "            continue", "        if line.raw.strip():", "            held_comments.append(line.raw)", "            continue", "        reflowed.extend(held_comments)", "        held_comments.clear()", "        reflowed.append(line.raw)", "    reflowed.extend(held_comments)", "", "    leftovers = [", "        line", "        for line in local.lines", "        if line.index not in consumed and (line.is_assignment or line.is_commented_assignment)", "    ]", "    if leftovers:", "        if reflowed and reflowed[-1].strip():", "            reflowed.append(\"\")", "        reflowed.append(_REFLOW_LOCAL_ONLY_HEADER)", "        reflowed.extend(line.raw for line in leftovers)", "    return reflowed", "", "", "def compute_reflow(pair: EnvPair) -> ReflowResult:", "    \"\"\"Compute a local file rewritten into its example's order and comment structure.", "", "    Every assignment kept is the local file's own ``raw`` line, moved rather than", "    rebuilt, so existing values survive quoting and spacing untouched. Nothing is", "    added: an example key with no local counterpart is skipped, because seeding", "    missing keys is ``--apply``'s job. Nothing is deleted either -- assignments with", "    no example counterpart are appended under :data:`_REFLOW_LOCAL_ONLY_HEADER`.", "", "    Three states are refused up front rather than reordered, all before the", "    round-trip guard runs:", "", "    - A line the parser does not recognise, which in practice means a multiline", "      quoted value. Parsing is line-oriented, so such a value reads as one", "      assignment plus continuation lines carrying no key; those are neither placed", "      nor kept as leftovers, and :func:`_assignment_multiset` would then compare", "      the truncated output *equal* to the original. The guard would report success", "      and write a file with an unterminated quote, which dotenv cannot parse at", "      all -- losing every key after it too. This is the one corruption the guard", "      cannot see, hence a pre-check rather than a stronger comparison.", "    - A key assigned twice as an active line, because dotenv resolution is", "      last-wins and reordering would change which assignment takes effect.", "    - An active value referencing another variable, because dotenv resolves", "      ``${NAME}`` against the keys above it, so a move can change the resolved", "      value while every raw line stays byte-identical.", "", "    A symlinked local path is refused for a different reason: the read follows the", "    link but :func:`os.replace` would replace the link itself, leaving a stale", "    regular file where a link to a managed location used to be.", "", "    :param pair: The example/local pair to reflow.", "    :type pair: EnvPair", "    :return: The computed lines plus the verdict of the pre-check and round-trip guard.", "    :rtype: ReflowResult", "    \"\"\"", "    if pair.local_path.is_symlink():", "        return ReflowResult(", "            pair=pair,", "            reflowed_lines=(),", "            changed=False,", "            aborted=True,", "            abort_reason=(", "                \"local file is a symlink; reflow replaces the path atomically, which \"", "                \"would swap the link itself for a regular file and detach it from its \"", "                \"target. Reflow the target directly instead; nothing was written\"", "            ),", "        )", "", "    # Read once and parse the same text: computing `changed` from a second read", "    # would compare against content the round-trip guard never validated.", "    original_text = pair.local_path.read_text(encoding=\"utf-8\")", "    local = _parse_env_text(original_text, pair.local_path)", "    example = parse_env_file(pair.example_path)", "", "    if reason := _reflow_refusal_reason(local, example, pair.example_path.name):", "        return ReflowResult(", "            pair=pair,", "            reflowed_lines=(),", "            changed=False,", "            aborted=True,", "            abort_reason=reason,", "            original_text=original_text,", "        )", "", "    reflowed = _reflow_lines(local, example)", "", "    text = \"\\n\".join(reflowed)", "    if reflowed:", "        text += \"\\n\"", "", "    abort_reason = _reflow_abort_reason(local, _parse_env_text(text, pair.local_path))", "    return ReflowResult(", "        pair=pair,", "        reflowed_lines=tuple(reflowed),", "        changed=text != original_text,", "        aborted=abort_reason is not None,", "        abort_reason=abort_reason,", "        original_text=original_text,", "    )", "", "", "def _atomic_write_text(path: Path, text: str) -> None:", "    \"\"\"Replace a file's content without any partial state ever being observable.", "", "    The temp file is created in the target's own directory so ``os.replace`` is a", "    same-filesystem rename: readers see either the old file or the new one, and a", "    crash leaves the original intact.", "", "    ``mkstemp`` creates the temp file 0600, so an existing target's permission bits", "    are copied over before the rename. Without that, rewriting a 0644 local env file", "    would silently tighten it to 0600 -- benign for a secret on its own, but enough", "    to break a bind-mounted env file another uid reads.", "", "    :param path: File to replace.", "    :type path: Path", "    :param text: Full new content.", "    :type text: str", "    :raises OSError: If the temp file cannot be written or the rename fails.", "    \"\"\"", "    handle_fd, temp_name = tempfile.mkstemp(", "        dir=str(path.parent), prefix=f\"{path.name}.\", suffix=\".tmp\"", "    )", "    temp_path = Path(temp_name)", "    try:", "        handle = os.fdopen(handle_fd, \"w\", encoding=\"utf-8\")", "    except BaseException:", "        os.close(handle_fd)", "        temp_path.unlink(missing_ok=True)", "        raise", "    try:", "        with handle:", "            handle.write(text)", "        try:", "            shutil.copymode(path, temp_path)", "        except FileNotFoundError:", "            # No existing target, so there is no mode to carry over; keep mkstemp's", "            # restrictive 0600 rather than inventing one from the umask.", "            pass", "        os.replace(temp_path, path)", "    except BaseException:", "        temp_path.unlink(missing_ok=True)", "        raise", "", "", "@dataclass(frozen=True)", "class ReflowApplication:", "    \"\"\"What :func:`apply_reflow` did, and whether the pair refused to reflow.", "", "    ``refused`` cannot be read off :attr:`ReflowResult.aborted` alone: the", "    concurrent-edit check runs at write time, after ``compute_reflow`` has already", "    returned a result that is not aborted. Reporting it only as a message left the", "    CLI exiting 0 on a refusal it had just printed.", "    \"\"\"", "", "    messages: tuple[str, ...]", "    refused: bool", "", "", "def apply_reflow(result: ReflowResult, repo_root: Path) -> ReflowApplication:", "    \"\"\"Write a computed reflow, or report why it was refused.", "", "    Refuses when the local file no longer holds the content the round-trip guard", "    validated, so a concurrent edit is reported rather than overwritten.", "", "    :param result: Output of :func:`compute_reflow`.", "    :type result: ReflowResult", "    :param repo_root: Repository root used to render display paths.", "    :type repo_root: Path", "    :return: Human-readable actions for the caller to print, and whether this pair", "        refused to reflow.", "    :rtype: ReflowApplication", "    \"\"\"", "    local_display = _relative_to_repo(result.pair.local_path, repo_root)", "    if result.aborted:", "        return ReflowApplication((f\"ABORTED {local_display}: {result.abort_reason}\",), True)", "    if not result.changed:", "        return ReflowApplication((f\"{local_display} already matches its example's order\",), False)", "", "    # The round-trip guard validated a snapshot taken in compute_reflow. os.replace", "    # makes the write atomic, but atomicity does not prevent a lost update: an", "    # editor autosave landing in between would be silently overwritten by content", "    # computed from the pre-autosave file. Re-read and refuse instead.", "    if result.pair.local_path.read_text(encoding=\"utf-8\") != result.original_text:", "        return ReflowApplication(", "            (", "                f\"ABORTED {local_display}: the file changed after the reflow was computed, \"", "                \"so writing it would discard that edit. Re-run --reflow; nothing was written\",", "            ),", "            True,", "        )", "", "    text = \"\\n\".join(result.reflowed_lines)", "    if result.reflowed_lines:", "        text += \"\\n\"", "    _atomic_write_text(result.pair.local_path, text)", "    example_display = _relative_to_repo(result.pair.example_path, repo_root)", "    return ReflowApplication((f\"reflowed {local_display} into {example_display} order\",), False)", "", "", "def build_parser() -> argparse.ArgumentParser:", "    \"\"\"Build the CLI argument parser.\"\"\"", "    parser = argparse.ArgumentParser(", "        description=\"Detect and sync local .env files from example templates.\",", "        formatter_class=argparse.RawDescriptionHelpFormatter,", "        epilog=\"\"\"", "Examples:", "  python -m tools.env_sync", "  python -m tools.env_sync --apply", "  python -m tools.env_sync --apply --prune", "  python -m tools.env_sync --mirror", "  python -m tools.env_sync --mirror --file .feeds.env", "  python -m tools.env_sync --reflow", "  python -m tools.env_sync --reflow --file .feeds.env", "  python -m tools.env_sync --migrate-canonical", "  python -m tools.env_sync --check", "  python -m tools.env_sync --render-sections", "  python -m tools.env_sync --compare-sections old.env.template .env.template", "  python -m tools.env_sync --file .feeds.env", "        \"\"\",", "    )", "    parser.add_argument(", "        \"--apply\",", "        action=\"store_true\",", "        help=\"Apply missing template entries to local env files.\",", "    )", "    parser.add_argument(", "        \"--prune\",", "        action=\"store_true\",", "        help=\"Remove extra local keys that no longer exist in the example template.\",", "    )", "    parser.add_argument(", "        \"--mirror\",", "        action=\"store_true\",", "        help=(", "            \"Reconcile the local file's key set with the example: add missing keys \"", "            \"AND prune extras in one pass. Existing local values are preserved. \"", "            \"Composable with --file.\"", "        ),", "    )", "    parser.add_argument(", "        \"--reflow\",", "        action=\"store_true\",", "        help=(", "            \"Rewrite local env files into their example's order and comment structure, \"", "            \"preserving existing values. Aborts without writing if any key or value \"", "            \"would change. Composable with --file.\"", "        ),", "    )", "    parser.add_argument(", "        \"--migrate-canonical\",", "        action=\"store_true\",", "        help=(", "            \"Move canonical QUEUE_URL_* values from per-service env files into env/.env, \"", "            \"preserving values exactly, and prune the dead legacy *_QUEUE_URL keys. \"", "            \"Refuses without writing if one key carries conflicting values.\"", "        ),", "    )", "    parser.add_argument(", "        \"--check\",", "        action=\"store_true\",", "        help=(", "            \"Exit with code 1 when any env pair is out of sync, or when a \"", "            \"committed example file carries keys absent from the deploy \"", "            \".env.template (template-superset drift).\"", "        ),", "    )", "    parser.add_argument(", "        \"--check-template\",", "        action=\"store_true\",", "        help=(", "            \"Exit with code 1 when a committed example file carries keys absent \"", "            \"from the deploy .env.template. Checks only committed files, so it is \"", "            \"deterministic in CI where developer-local env files do not exist.\"", "        ),", "    )", "    parser.add_argument(", "        \"--file\",", "        default=None,", "        help=\"Target a single env pair by local filename/path or example filename/path.\",", "    )", "    parser.add_argument(", "        \"--render-sections\",", "        action=\"store_true\",", "        help=\"Print the simulated ConfigMap key set for every datalake release.\",", "    )", "    parser.add_argument(", "        \"--template\",", "        default=_TEMPLATE_RELATIVE_PATH,", "        help=(", "            \"Deploy template used by --render-sections, --check-template and the \"", "            \"superset half of --check (default: .env.template).\"", "        ),", "    )", "    parser.add_argument(", "        \"--compare-sections\",", "        nargs=2,", "        metavar=(\"OLD_TEMPLATE\", \"NEW_TEMPLATE\"),", "        help=\"Print per-release keys removed and added between two templates.\",", "    )", "    return parser", "", "", "@dataclass(frozen=True)", "class _SupersetScan:", "    \"\"\"Everything the template-side gates need, derived once per run.", "", "    Named rather than returned as a tuple for the same reason as", "    :class:`_TemplateCheckOutcome`: each call site consumes a different subset,", "    and widening a tuple to add one more is how a field comes to be dropped at", "    one site and not the other.", "    \"\"\"", "", "    reports: list[TemplateSupersetReport]", "    violations: tuple[SectionValidationViolation, ...]", "    scope: tuple[ParsedEnvFile, dict[str, Path], tuple[SectionValidationViolation, ...]] | None", "    exit_code: int", "", "", "def _scan_template_superset(", "    repo_root: Path, template_path: Path, gating: bool = True", ") -> _SupersetScan:", "    \"\"\"Derive the template-side inputs, turning a missing or unreadable template into exit 2.", "", "    ``--template`` widened the template argument from a fixed repo path to", "    arbitrary user input, so a directory or unreadable file has to surface as the", "    CLI's documented error status rather than an uncaught OSError traceback.", "", "    A *missing* template is the same failure and must also be nonzero on a gate,", "    never a quiet success: the template is the source of truth every example is", "    compared against, so treating absence as \"nothing to check\" meant a change", "    deleting both the template and the shared example passed vacuously. A", "    non-gating run only reports, so it warns and drops the template-side half", "    rather than failing a caller that has no drift to answer for.", "", "    :param repo_root: Repository root used to resolve the example paths.", "    :type repo_root: Path", "    :param template_path: Already-resolved template path to read.", "    :type template_path: Path", "    :param gating: True when the caller's exit code gates a commit or a build.", "    :type gating: bool", "    :return: The reports, the coverage violations, the shared scope, and an exit", "        code; on failure, nothing and code 2 (0 when not gating) with the reason", "        already printed.", "    :rtype: _SupersetScan", "    \"\"\"", "    failure_code = 2 if gating else 0", "    report_failure = _error if gating else _warn", "", "    if not template_path.exists():", "        report_failure(", "            f\"Deploy template not found: {_relative_to_repo(template_path, repo_root)}. \"", "            \"It is the source of truth every example is checked against; restore it \"", "            \"or pass an existing --template.\"", "        )", "        return _SupersetScan([], (), None, failure_code)", "", "    try:", "        scope = _derive_template_scope(repo_root, template_path)", "        parsed_template, example_map, violations = scope", "        reports = [", "            analyze_template_superset(example_path, template_path, parsed_template)", "            for example_path in sorted(example_map.values())", "        ]", "    except OSError as exc:", "        report_failure(str(exc))", "        return _SupersetScan([], (), None, failure_code)", "    return _SupersetScan(reports, violations, scope, 0)", "", "", "@dataclass(frozen=True)", "class _TemplateCheckOutcome:", "    \"\"\"The template-side half of ``--check``: what was found and whether to fail.", "", "    Named rather than returned as a tuple because every template-side invariant", "    has to reach the exit code. Growing this by one more analysis previously meant", "    widening a tuple at each call site, which is how section alignment came to be", "    printed by ``--check-template`` but not gated by ``--check``.", "    \"\"\"", "", "    reports: tuple[TemplateSupersetReport, ...]", "    coverage_violations: tuple[SectionValidationViolation, ...]", "    alignment_report: ExampleSectionAlignmentReport | None", "    exit_code: int", "", "    @property", "    def has_drift(self) -> bool:", "        \"\"\"Return True when any template-side invariant is violated.\"\"\"", "        return (", "            any(report.has_drift for report in self.reports)", "            or bool(self.coverage_violations)", "            or (self.alignment_report is not None and self.alignment_report.has_drift)", "        )", "", "", "def _superset_reports_for_check(repo_root: Path, args: argparse.Namespace) -> _TemplateCheckOutcome:", "    \"\"\"Run and print the whole-repo template half of ``--check``.", "", "    Covers the same three template-side invariants ``--check-template`` gates on", "    that do not need the deploy chart: the per-file subset rule, the", "    section/example coverage reconciliation, and section alignment. Marker", "    validation stays exclusive to ``--check-template``, which is the committed-files", "    gate wired into pre-commit and CI.", "", "    The invariants compare committed files only, so they are skipped when the", "    caller scopes the run to a single ``--file`` pair.", "", "    :param repo_root: Repository root used to resolve the example paths.", "    :type repo_root: Path", "    :param args: Parsed CLI arguments; ``file``, ``check`` and ``template`` are consulted.", "    :type args: argparse.Namespace", "    :return: What each analysis found, and an exit code; on an unreadable template,", "        nothing and code 2 under ``--check``, else nothing and code 0 with the", "        reason already printed.", "    :rtype: _TemplateCheckOutcome", "    \"\"\"", "    if args.file is not None:", "        return _TemplateCheckOutcome((), (), None, 0)", "", "    template_path = _resolve_template_path(args.template, repo_root)", "    # Only --check gates a commit or a build; a bare report run and --apply have", "    # already done their pair-side work and must not fail on the template's absence.", "    scan = _scan_template_superset(repo_root, template_path, gating=args.check)", "    if scan.scope is None:", "        return _TemplateCheckOutcome((), (), None, scan.exit_code)", "", "    if scan.reports:", "        print(\"\")", "        print(format_template_superset_reports(scan.reports, repo_root))", "    if scan.violations:", "        print(\"\")", "        print(format_example_coverage_violations(scan.violations, template_path, repo_root))", "", "    # Reuses the scan's parsed template and section map rather than re-deriving", "    # them, so this analysis and the superset reports above cannot disagree.", "    try:", "        alignment_report, _ = analyze_example_section_alignment(", "            repo_root, template_path, scan.scope", "        )", "    except OSError as exc:", "        _error(str(exc))", "        return _TemplateCheckOutcome((), (), None, 2)", "    # Printed only on drift, matching the coverage block above; --check-template", "    # is the verbose view that confirms each invariant passed.", "    if alignment_report.has_drift:", "        print(\"\")", "        print(format_example_section_alignment_report(alignment_report, repo_root))", "", "    return _TemplateCheckOutcome(tuple(scan.reports), scan.violations, alignment_report, 0)", "", "", "def _run_template_superset_check(repo_root: Path, template_path: Path | None = None) -> int:", "    \"\"\"Print and gate on template superset and section-routing invariants.", "", "    :param repo_root: Repository root used to resolve the example paths.", "    :type repo_root: Path", "    :param template_path: Template to check against. Defaults to the committed", "        ``.env.template`` at the repository root.", "    :type template_path: Path | None", "    :return: 1 on superset drift or section violations, 2 when the template is", "        missing or cannot be read, else 0.", "    :rtype: int", "    \"\"\"", "    if template_path is None:", "        template_path = repo_root / _TEMPLATE_RELATIVE_PATH", "    scan = _scan_template_superset(repo_root, template_path)", "    if scan.exit_code:", "        return scan.exit_code", "", "    if scan.reports:", "        print(format_template_superset_reports(scan.reports, repo_root))", "        print(\"\")", "    print(format_example_coverage_violations(scan.violations, template_path, repo_root))", "", "    print(\"\")", "    try:", "        section_report = analyze_section_validation(template_path)", "        # Reuses the scan's parsed template and section map rather than re-deriving", "        # them; the reconciliation violations it returns are the same ones already", "        # printed above, so they are dropped here rather than reported twice.", "        alignment_report, _ = analyze_example_section_alignment(", "            repo_root, template_path, scan.scope", "        )", "    except OSError as exc:", "        _error(str(exc))", "        return 2", "    print(format_section_validation_report(section_report, repo_root))", "    print(\"\")", "    print(format_example_section_alignment_report(alignment_report, repo_root))", "", "    has_superset_drift = any(report.has_drift for report in scan.reports)", "    if (", "        has_superset_drift", "        or section_report.has_violations", "        or alignment_report.has_drift", "        or scan.violations", "    ):", "        return 1", "    return 0", "", "", "def _reflow_flag_conflicts(args: argparse.Namespace) -> list[str]:", "    \"\"\"Return the flags given alongside ``--reflow`` that it cannot be combined with.", "", "    Reflow reorders; the other modes add, prune, check, or print a report and exit.", "    A combined run has no well-defined meaning and its abort semantics would be", "    ambiguous, so the combination is an error rather than a silent interaction.", "", "    :param args: Parsed CLI arguments.", "    :type args: argparse.Namespace", "    :return: Names of the conflicting flags supplied, in a stable order.", "    :rtype: list[str]", "    \"\"\"", "    return [", "        name", "        for name, enabled in (", "            (\"--apply\", args.apply),", "            (\"--mirror\", args.mirror),", "            (\"--prune\", args.prune),", "            (\"--check\", args.check),", "            (\"--check-template\", args.check_template),", "            (\"--render-sections\", args.render_sections),", "            (\"--compare-sections\", bool(args.compare_sections)),", "            (\"--migrate-canonical\", args.migrate_canonical),", "        )", "        if enabled", "    ]", "", "", "@dataclass(frozen=True)", "class _CanonicalObservation:", "    \"\"\"One canonical queue assignment as found in a per-service local env file.\"\"\"", "", "    display_path: str", "    value: str", "", "", "@dataclass(frozen=True)", "class _MigrationFileChange:", "    \"\"\"A file's fully computed replacement text plus the snapshot it was derived from.", "", "    ``original_text`` is None when the file did not exist at collection time, so", "    the write-time re-read can tell \"still absent\" from \"created underneath us\"", "    instead of comparing a real body against an empty string.", "    \"\"\"", "", "    path: Path", "    original_text: str | None", "    new_text: str", "", "    @property", "    def changed(self) -> bool:", "        \"\"\"Return True when writing this would alter the file.\"\"\"", "        return self.new_text != self.original_text", "", "", "@dataclass(frozen=True)", "class _DestinationPlan:", "    \"\"\"What ``env/.env`` needs per canonical key, decided before anything is written.\"\"\"", "", "    replacements: dict[str, str]", "    additions: tuple[str, ...]", "    satisfied: tuple[str, ...]", "    conflicts: dict[str, tuple[str, str]]", "", "", "def _render_env_text(lines: Sequence[str]) -> str:", "    \"\"\"Join env lines into file content, terminating a non-empty file with a newline.", "", "    :param lines: Raw lines without terminators.", "    :type lines: Sequence[str]", "    :return: The file body to write.", "    :rtype: str", "    \"\"\"", "    text = \"\\n\".join(lines)", "    return f\"{text}\\n\" if lines else text", "", "", "def _migratable_pairs(pairs: Sequence[EnvPair], repo_root: Path) -> list[EnvPair]:", "    \"\"\"Keep only the per-service pairs ``--migrate-canonical`` reads and prunes.", "", "    ``discover_env_pairs`` also yields the shared ``env/.env`` pair -- the migration", "    *destination*, not a source -- ``env/.local_data_loads.env``, whose keys belong to", "    local-only tooling, and one pair per ``tools/*/.env.example``, all of which map", "    onto the hand-managed ``.local/.env`` holding real developer credentials.", "    ``reflowable_pairs`` already excludes that last group for the same reason.", "", "    The set is derived from :data:`SERVICE_RELEASES` through the same", "    :func:`_expected_example_path` mapping the section checks use, so a new service", "    release is picked up automatically instead of needing a second list kept in sync.", "", "    :param pairs: Discovered example/local pairs.", "    :type pairs: Sequence[EnvPair]", "    :param repo_root: Repository root used to render comparable relative paths.", "    :type repo_root: Path", "    :return: The per-service pairs, ordered by :data:`SERVICE_RELEASES`.", "    :rtype: list[EnvPair]", "    \"\"\"", "    wanted = _migratable_example_paths()", "    selected: list[tuple[int, EnvPair]] = []", "    for pair in pairs:", "        relative = _relative_to_repo(pair.example_path, repo_root)", "        if relative in wanted:", "            selected.append((wanted[relative], pair))", "    return [pair for _, pair in sorted(selected, key=lambda item: item[0])]", "", "", "def _collect_canonical_assignments(", "    parsed_sources: Sequence[ParsedEnvFile], repo_root: Path", ") -> tuple[dict[str, EnvLine], dict[str, list[_CanonicalObservation]]]:", "    \"\"\"Gather every canonical queue assignment across the per-service local files.", "", "    An empty-valued assignment is recorded as an observation but never becomes the", "    winner: an empty value is not a value, so it must not win over a real one and", "    must not read as disagreement with one. That mirrors the destination policy,", "    where DAT-8391's deliberately empty seeds count as unconfigured. Emptiness is", "    judged by :func:`_dotenv_value_is_empty`, so the quoted spellings count too.", "", "    Built from ``parsed.lines`` rather than the ``active_entries`` that", "    :func:`_plan_source_prunes` reads. That property is a last-wins dict, so a file", "    assigning the same key twice would collapse to a single observation and the", "    winner would flip from the first non-empty assignment to the last. The prune", "    planner only needs the key set, so the asymmetry is deliberate rather than a", "    divergence -- the same reason :func:`_assignment_multiset` reads ``lines``.", "", "    :param parsed_sources: Parsed per-service local files, in pair order.", "    :type parsed_sources: Sequence[ParsedEnvFile]", "    :param repo_root: Repository root used to render display paths.", "    :type repo_root: Path", "    :return: The first non-empty assignment line per key, and every observation per key.", "    :rtype: tuple[dict[str, EnvLine], dict[str, list[_CanonicalObservation]]]", "    \"\"\"", "    winners: dict[str, EnvLine] = {}", "    observations: dict[str, list[_CanonicalObservation]] = {}", "    for parsed in parsed_sources:", "        display = _relative_to_repo(parsed.path, repo_root)", "        for line in parsed.lines:", "            if not line.is_assignment or line.key is None:", "                continue", "            if not _is_canonical_queue_key(line.key):", "                continue", "            value = line.value or \"\"", "            observations.setdefault(line.key, []).append(", "                _CanonicalObservation(display_path=display, value=value)", "            )", "            if not _dotenv_value_is_empty(value) and line.key not in winners:", "                winners[line.key] = line", "    return winners, observations", "", "", "def _canonical_value_conflicts(", "    observations: dict[str, list[_CanonicalObservation]],", ") -> dict[str, list[_CanonicalObservation]]:", "    \"\"\"Return the keys whose per-service files disagree about a real value.", "", "    Two files carrying the same value are a safe dedupe, not a conflict, and an", "    empty value is unconfigured rather than disagreeing.", "", "    :param observations: Every canonical observation per key.", "    :type observations: dict[str, list[_CanonicalObservation]]", "    :return: Key to the non-empty observations, only for keys with 2+ distinct values.", "    :rtype: dict[str, list[_CanonicalObservation]]", "    \"\"\"", "    conflicts: dict[str, list[_CanonicalObservation]] = {}", "    for key, entries in observations.items():", "        configured = [entry for entry in entries if not _dotenv_value_is_empty(entry.value)]", "        if len({entry.value for entry in configured}) > 1:", "            conflicts[key] = configured", "    return conflicts", "", "", "def _plan_destination(", "    winners: dict[str, EnvLine],", "    destination: ParsedEnvFile | None,", "    seed: ParsedEnvFile | None,", ") -> _DestinationPlan:", "    \"\"\"Decide what ``env/.env`` needs for each canonical key without writing anything.", "", "    Five destination states exist per key and only one is a real conflict:", "", "    - absent -> append the source assignment verbatim", "    - present and empty -> replace (DAT-8391 seeded these empty on purpose);", "      ``KEY=``, ``KEY=\"\"`` and ``KEY=''`` all count, per", "      :func:`_dotenv_value_is_empty`", "    - present and exactly the committed ``env/.env.example`` value -> replace", "      (an unedited seed or placeholder, read at run time so this keeps holding", "      after the seeds change from empty to placeholder URLs)", "    - present with the source value -> satisfied; nothing is written for this key.", "      No duplicate is appended, and any duplicate lines the destination already", "      carried are left exactly as they are: the key never enters ``replacements``,", "      so :func:`_rewrite_with_replacements`'s first-line-wins dedupe -- which only", "      applies to keys being rewritten -- never touches it. Harmless, since dotenv", "      resolves the key to the last assignment and identical duplicates agree", "    - present with some other real value -> conflict; refuse the whole run", "", "    Each state is judged from ``active_entries``, which keeps the *last* assignment", "    for a repeated key. A key assigned more than once with disagreeing values is", "    therefore not decidable here and is refused upstream by", "    :func:`_destination_duplicate_conflicts` before this plan is acted on.", "", "    :param winners: The assignment line to relocate, per canonical key.", "    :type winners: dict[str, EnvLine]", "    :param destination: Parsed ``env/.env``, or None when it does not exist yet.", "    :type destination: ParsedEnvFile | None", "    :param seed: Parsed ``env/.env.example``, or None when it cannot be read.", "    :type seed: ParsedEnvFile | None", "    :return: Replacements, appends, already-satisfied keys, and conflicts.", "    :rtype: _DestinationPlan", "    \"\"\"", "    destination_entries = destination.active_entries if destination is not None else {}", "    seed_entries = seed.active_entries if seed is not None else {}", "", "    replacements: dict[str, str] = {}", "    additions: list[str] = []", "    satisfied: list[str] = []", "    conflicts: dict[str, tuple[str, str]] = {}", "", "    for key, line in winners.items():", "        source_value = line.value or \"\"", "        existing = destination_entries.get(key)", "        if existing is None:", "            additions.append(line.raw)", "            continue", "        existing_value = existing.value or \"\"", "        seed_line = seed_entries.get(key)", "        seed_value = (seed_line.value or \"\") if seed_line is not None else None", "        if existing_value == source_value:", "            satisfied.append(key)", "        elif _dotenv_value_is_empty(existing_value) or existing_value == seed_value:", "            replacements[key] = line.raw", "        else:", "            conflicts[key] = (existing_value, source_value)", "", "    return _DestinationPlan(", "        replacements=replacements,", "        additions=tuple(additions),", "        satisfied=tuple(satisfied),", "        conflicts=conflicts,", "    )", "", "", "def _carries_a_canonical_value(parsed: ParsedEnvFile) -> bool:", "    \"\"\"Return True when this file assigns at least one canonical key a real value.", "", "    Emptiness is judged by :func:`_dotenv_value_is_empty`, matching both", "    :func:`_collect_canonical_assignments` and :func:`_plan_destination`: DAT-8391's", "    deliberately empty seeds are unconfigured, so a destination holding only those", "    still needs filling from the rendered ConfigMap.", "", "    :param parsed: Parsed env file, typically the post-write ``env/.env``.", "    :type parsed: ParsedEnvFile", "    :return: True when some canonical ``QUEUE_URL_*`` key has a non-empty value.", "    :rtype: bool", "    \"\"\"", "    return any(", "        _is_canonical_queue_key(key) and not _dotenv_value_is_empty(entry.value)", "        for key, entry in parsed.active_entries.items()", "    )", "", "", "def _destination_duplicate_conflicts(", "    destination: ParsedEnvFile | None, winners: dict[str, EnvLine]", ") -> dict[str, list[str]]:", "    \"\"\"Return canonical keys whose destination carries duplicate, disagreeing lines.", "", "    ``active_entries`` collapses a repeated key to its *last* line -- what dotenv", "    loads -- while :func:`_rewrite_with_replacements` replaces the *first* and drops", "    the rest. When the duplicates disagree those two ends pick different lines: a", "    real value on the first line would be judged by the last line's text, classified", "    replaceable because that last line happens to be an empty or seed placeholder,", "    then overwritten -- deleting a value that exists nowhere else, with no conflict", "    reported. Rather than guess which duplicate the developer meant, refuse the run.", "", "    Identical duplicates are safe to let through: every candidate line carries the", "    same text, so whichever end picks which line, the value is the same. Letting", "    them through is not the same as collapsing them -- on the ``satisfied`` path", "    nothing is rewritten and both lines survive; see", "    :func:`_plan_destination`. Keys that are not being migrated are ignored,", "    since no line of theirs is rewritten.", "", "    :param destination: Parsed ``env/.env``, or None when it does not exist yet.", "    :type destination: ParsedEnvFile | None", "    :param winners: The canonical keys this run intends to migrate.", "    :type winners: dict[str, EnvLine]", "    :return: Distinct duplicate values per offending key, in first-seen order.", "    :rtype: dict[str, list[str]]", "    \"\"\"", "    if destination is None:", "        return {}", "", "    seen: dict[str, list[str]] = {}", "    for line in destination.lines:", "        if not line.is_assignment or line.key is None or line.key not in winners:", "            continue", "        seen.setdefault(line.key, []).append(line.value or \"\")", "", "    duplicates: dict[str, list[str]] = {}", "    for key, values in seen.items():", "        distinct = list(dict.fromkeys(values))", "        if len(distinct) > 1:", "            duplicates[key] = distinct", "    return duplicates", "", "", "def _rewrite_with_replacements(", "    raw_lines: Sequence[str], replacements: dict[str, str], drop_keys: set[str]", ") -> list[str]:", "    \"\"\"Replace or drop active assignment lines in one pass, dropping duplicates.", "", "    A replaced key keeps only its first active line; any further active line for", "    the same key is dropped rather than replaced, so a file that already carried", "    the key twice does not end up with two copies of the migrated value. Follows", "    :func:`_prune_extra_keys` in also removing the sync marker comment above a", "    line it removes.", "", "    :param raw_lines: The file's current lines.", "    :type raw_lines: Sequence[str]", "    :param replacements: Key to the raw line text that replaces its assignment.", "    :type replacements: dict[str, str]", "    :param drop_keys: Keys whose active assignment lines are removed outright.", "    :type drop_keys: set[str]", "    :return: The rewritten lines.", "    :rtype: list[str]", "    \"\"\"", "    emitted: set[str] = set()", "    kept: list[str] = []", "    for index, raw in enumerate(raw_lines):", "        parsed = _parse_line(raw, index)", "        key = parsed.key", "        if parsed.is_assignment and key is not None:", "            if key in drop_keys or (key in replacements and key in emitted):", "                if kept and kept[-1].startswith(_SYNC_MARKER):", "                    kept.pop()", "                continue", "            if key in replacements:", "                emitted.add(key)", "                kept.append(replacements[key])", "                continue", "        kept.append(raw)", "    return kept", "", "", "def _append_migrated_assignments(lines: list[str], additions: Sequence[str]) -> None:", "    \"\"\"Append the relocated assignments under one header, mutating ``lines`` in place.", "", "    The raw assignment text is carried over verbatim rather than reformatted from", "    ``key`` and ``value``, so quoting and spacing survive byte-identical.", "", "    :param lines: Destination lines to extend.", "    :type lines: list[str]", "    :param additions: Raw assignment lines to append.", "    :type additions: Sequence[str]", "    :return: None; ``lines`` is mutated.", "    :rtype: None", "    \"\"\"", "    if not additions:", "        return", "    if lines and lines[-1].strip():", "        lines.append(\"\")", "    lines.append(_MIGRATION_HEADER)", "    lines.extend(additions)", "", "", "def _migrate_flag_conflicts(args: argparse.Namespace) -> list[str]:", "    \"\"\"Return the flags given alongside ``--migrate-canonical`` that it cannot join.", "", "    Migration relocates values across files; the other modes add, prune, reorder,", "    check, or print a report and exit. A combined run has no defined abort", "    semantics, so the combination is an error rather than a silent interaction --", "    the same rule :func:`_reflow_flag_conflicts` enforces. ``--file`` is rejected", "    too: the migration is whole-tree by construction (it merges eight sources into", "    one destination), so a single-pair scope would silently mean nothing.", "", "    :param args: Parsed CLI arguments.", "    :type args: argparse.Namespace", "    :return: Names of the conflicting flags supplied, in a stable order.", "    :rtype: list[str]", "    \"\"\"", "    return [", "        name", "        for name, enabled in (", "            (\"--apply\", args.apply),", "            (\"--mirror\", args.mirror),", "            (\"--prune\", args.prune),", "            (\"--check\", args.check),", "            (\"--check-template\", args.check_template),", "            (\"--render-sections\", args.render_sections),", "            (\"--compare-sections\", bool(args.compare_sections)),", "            (\"--reflow\", args.reflow),", "            (\"--file\", args.file is not None),", "        )", "        if enabled", "    ]", "", "", "def _report_migration_conflicts(", "    value_conflicts: dict[str, list[_CanonicalObservation]],", "    destination_conflicts: dict[str, tuple[str, str]],", "    duplicate_conflicts: dict[str, list[str]],", "    observations: dict[str, list[_CanonicalObservation]],", "    destination_display: str,", ") -> None:", "    \"\"\"Print every reason the migration refused, naming each disagreeing file and value.", "", "    Refusal is whole-run rather than per-key, so every conflict is reported in one", "    pass: a developer fixing them one re-run at a time would otherwise discover", "    them one at a time.", "", "    :param value_conflicts: Per-service disagreements from :func:`_canonical_value_conflicts`.", "    :type value_conflicts: dict[str, list[_CanonicalObservation]]", "    :param destination_conflicts: Key to ``(destination value, source value)``.", "    :type destination_conflicts: dict[str, tuple[str, str]]", "    :param duplicate_conflicts: Disagreeing duplicate destination values per key, from", "        :func:`_destination_duplicate_conflicts`.", "    :type duplicate_conflicts: dict[str, list[str]]", "    :param observations: Every canonical observation per key, used to name the source file.", "    :type observations: dict[str, list[_CanonicalObservation]]", "    :param destination_display: Repository-relative path of ``env/.env``.", "    :type destination_display: str", "    :return: None; messages go to stderr.", "    :rtype: None", "    \"\"\"", "    for key, values in sorted(duplicate_conflicts.items()):", "        disagreement = \", \".join(values)", "        _error(", "            f\"{key} is assigned more than once in {destination_display} with different \"", "            f\"values: {disagreement}. Nothing was written; delete the assignments you \"", "            \"do not want and re-run.\"", "        )", "    for key, entries in sorted(value_conflicts.items()):", "        disagreement = \", \".join(f\"{entry.display_path}={entry.value}\" for entry in entries)", "        _error(", "            f\"{key} carries conflicting values across per-service env files: \"", "            f\"{disagreement}. Nothing was written; reconcile them by hand and re-run.\"", "        )", "    for key, (existing_value, source_value) in sorted(destination_conflicts.items()):", "        source_display = next(", "            entry.display_path for entry in observations[key] if entry.value == source_value", "        )", "        _error(", "            f\"{key} already has a different value in {destination_display}: \"", "            f\"{destination_display}={existing_value} vs {source_display}={source_value}. \"", "            \"Nothing was written; keep the one you want and re-run.\"", "        )", "", "", "def _plan_source_prunes(", "    parsed_sources: Sequence[ParsedEnvFile],", "    source_texts: dict[Path, str],", "    repo_root: Path,", ") -> tuple[list[_MigrationFileChange], list[str]]:", "    \"\"\"Compute the per-service files' new text with their queue keys removed.", "", "    Both key families go: the canonical assignments have been relocated to", "    ``env/.env``, and the legacy ones are dead once DAT-7760 lands. Leaving either", "    behind would keep ``env_sync`` reporting drift on these files forever.", "", "    :param parsed_sources: Parsed per-service local files.", "    :type parsed_sources: Sequence[ParsedEnvFile]", "    :param source_texts: Collection-time snapshot text, keyed by path.", "    :type source_texts: dict[Path, str]", "    :param repo_root: Repository root used to render display paths.", "    :type repo_root: Path", "    :return: One change per file that has queue keys, and the matching action lines.", "    :rtype: tuple[list[_MigrationFileChange], list[str]]", "    \"\"\"", "    changes: list[_MigrationFileChange] = []", "    actions: list[str] = []", "    for parsed in parsed_sources:", "        canonical_keys = {key for key in parsed.active_entries if _is_canonical_queue_key(key)}", "        legacy_keys = {key for key in parsed.active_entries if _is_legacy_queue_key(key)}", "        if not canonical_keys and not legacy_keys:", "            continue", "        pruned_lines = _prune_extra_keys(", "            list(parsed.raw_lines), sorted(canonical_keys | legacy_keys)", "        )", "        changes.append(", "            _MigrationFileChange(", "                path=parsed.path,", "                original_text=source_texts[parsed.path],", "                new_text=_render_env_text(pruned_lines),", "            )", "        )", "        actions.append(", "            f\"pruned {len(canonical_keys)} canonical and {len(legacy_keys)} legacy \"", "            f\"queue key(s) from {_relative_to_repo(parsed.path, repo_root)}\"", "        )", "    return changes, actions", "", "", "def _relative_link_display(path: Path, repo_root: Path) -> str:", "    \"\"\"Return a repo-relative display path without following ``path`` itself.", "", "    :func:`_relative_to_repo` resolves the whole path, which for a symlink names the", "    target instead of the link. A refusal has to name the file the developer has to", "    deal with, so only the parent is resolved.", "", "    :param path: Path to display, possibly a symlink.", "    :type path: Path", "    :param repo_root: Repository root to render relative to.", "    :type repo_root: Path", "    :return: Repository-relative display path of the link itself.", "    :rtype: str", "    \"\"\"", "    parent = _relative_to_repo(path.parent, repo_root)", "    return path.name if parent == \".\" else f\"{parent}/{path.name}\"", "", "", "def _migration_symlink_exit_code(", "    destination_path: Path, pairs: Sequence[EnvPair], repo_root: Path", ") -> int:", "    \"\"\"Refuse the run when ``env/.env`` or any migratable source is a symlink.", "", "    Reads follow a link but :func:`_atomic_write_text`'s ``os.replace`` does not: it", "    would swap the link itself for a regular file, silently detaching a developer's", "    env file from the managed location it pointed at. The same reason", "    :func:`compute_reflow` refuses a symlinked local path.", "", "    Checked before anything is planned, so a refusal leaves both the link and its", "    target untouched.", "", "    :param destination_path: ``env/.env``, the migration destination.", "    :type destination_path: Path", "    :param pairs: The per-service pairs whose local files the migration prunes.", "    :type pairs: Sequence[EnvPair]", "    :param repo_root: Repository root used to render display paths.", "    :type repo_root: Path", "    :return: 1 when any involved path is a symlink, else 0.", "    :rtype: int", "    \"\"\"", "    refused = False", "    for path in [destination_path, *(pair.local_path for pair in pairs)]:", "        if not path.is_symlink():", "            continue", "        _error(", "            f\"{_relative_link_display(path, repo_root)} is a symlink; migration replaces the path \"", "            \"atomically, which would swap the link itself for a regular file and detach it \"", "            \"from its target. Migrate the target directly instead; nothing was written\"", "        )", "        refused = True", "    return 1 if refused else 0", "", "", "def _snapshot_verification_targets(", "    changes: Sequence[_MigrationFileChange],", "    source_texts: dict[Path, str],", "    seed_path: Path,", "    seed_text: str | None,", ") -> list[_MigrationFileChange]:", "    \"\"\"Return every file whose collection-time snapshot the plan depends on.", "", "    ``changes`` covers the destination and each source that needs pruning, but a", "    file needing no write still has to be re-read before the sources are pruned. The", "    sharp case is a destination that already carries the canonical value: its change", "    record is unchanged, so checking only the files about to be written would leave", "    the destination unverified and still prune the sources -- deleting the last copy", "    of a value an edit had just removed from ``env/.env``. Sources with no queue keys", "    are included for the same reason: they are read as part of deciding the winner.", "", "    The seed is read too, never written: :func:`_plan_destination` compares the", "    destination's value against it to decide whether that value is a real choice or", "    an unconfigured placeholder safe to replace. An edit landing there between", "    collection and write would make that classification stale, so it is verified on", "    the same terms as everything else the plan was derived from. Only when it", "    existed at collection time, matching ``source_texts``: a seed created mid-run", "    cannot invalidate a plan computed without one.", "", "    :param changes: The computed changes, destination first.", "    :type changes: Sequence[_MigrationFileChange]", "    :param source_texts: Collection-time snapshot text per source path.", "    :type source_texts: dict[Path, str]", "    :param seed_path: Path of the committed example the destination is judged against.", "    :type seed_path: Path", "    :param seed_text: Collection-time snapshot text, or None when the seed is absent.", "    :type seed_text: str | None", "    :return: The changes plus a no-op record for every file read but not written.", "    :rtype: list[_MigrationFileChange]", "    \"\"\"", "    planned = {change.path for change in changes}", "    read_only = dict(source_texts)", "    if seed_text is not None:", "        read_only[seed_path] = seed_text", "    unwritten = [", "        _MigrationFileChange(path=path, original_text=text, new_text=text)", "        for path, text in read_only.items()", "        if path not in planned", "    ]", "    return [*changes, *unwritten]", "", "", "def _concurrent_edit_exit_code(snapshots: Sequence[_MigrationFileChange], repo_root: Path) -> int:", "    \"\"\"Return a nonzero exit code when any file changed since the plan was computed.", "", "    ``os.replace`` makes each write atomic, but atomicity does not prevent a lost", "    update: an editor autosave landing between collection and write would be", "    silently overwritten by text computed from the pre-autosave file. Every file the", "    plan was derived from is checked -- not just the ones about to be written, see", "    :func:`_snapshot_verification_targets` -- and all of them before any write, so a", "    refusal leaves the whole tree untouched.", "", "    :param snapshots: Every file whose collection-time text the plan relies on.", "    :type snapshots: Sequence[_MigrationFileChange]", "    :param repo_root: Repository root used to render display paths.", "    :type repo_root: Path", "    :return: 1 on a concurrent edit, 2 when a file cannot be re-read, else 0.", "    :rtype: int", "    \"\"\"", "    for change in snapshots:", "        try:", "            current = change.path.read_text(encoding=\"utf-8\") if change.path.exists() else None", "        except OSError as exc:", "            _error(str(exc))", "            return 2", "        if current != change.original_text:", "            _error(", "                f\"{_relative_to_repo(change.path, repo_root)} changed after the migration was \"", "                \"computed, so writing it would discard that edit. Re-run \"", "                \"--migrate-canonical; nothing was written.\"", "            )", "            return 1", "    return 0", "", "", "# FUTURE: move _run_migrate_canonical and its ~15 private helpers into", "# tools/env_sync/migrate_canonical.py, leaving this module the flag wiring. The", "# migration mode is what pushes cli.py past 3100 lines. It is not a clean lift", "# though: the drift report's migration hint (_migration_hint_applies, called from", "# _render_report) reads _is_canonical_queue_key and _is_migratable_pair /", "# _migratable_example_paths, so those stay behind or move to a shared module", "# rather than travelling with the migration code. Deferred from the DAT-7760", "# review rather than done there: a mechanical split of a module this size would", "# have swamped the diff that actually removes the fallback.", "def _run_migrate_canonical(repo_root: Path, args: argparse.Namespace) -> int:", "    \"\"\"Relocate canonical queue URLs into ``env/.env`` and drop the dead legacy keys.", "", "    Moves every ``QUEUE_URL_*`` assignment out of the eight per-service local env", "    files into the shared ``env/.env``, preserving the assignment text verbatim, and", "    prunes the legacy ``*_QUEUE_URL`` keys that nothing reads once DAT-7760 lands --", "    from the sources and from ``env/.env`` itself. Without this, a developer whose", "    real values sit in the per-service files would lose them to ``--mirror --prune``", "    and have no working queue config once the fallback is gone.", "", "    Everything is computed before anything is written, every source and the", "    destination are re-read immediately before the write and compared against the", "    collection-time snapshot, and the destination is written before the sources are", "    pruned -- so a failure in between leaves values duplicated, never lost.", "", "    :param repo_root: Repository root used to discover and display env pairs.", "    :type repo_root: Path", "    :param args: Parsed CLI arguments, consulted for flag conflicts.", "    :type args: argparse.Namespace", "    :return: 1 on a value conflict, a symlinked env file, or a concurrent edit, 2 on", "        a bad invocation or IO error, else 0.", "    :rtype: int", "    \"\"\"", "    if conflicts := _migrate_flag_conflicts(args):", "        _error(f\"--migrate-canonical cannot be combined with {', '.join(conflicts)}\")", "        return 2", "", "    destination_path = repo_root / _MIGRATION_DESTINATION_PATH", "    seed_path = repo_root / _MIGRATION_DESTINATION_EXAMPLE_PATH", "    destination_display = _relative_to_repo(destination_path, repo_root)", "", "    try:", "        pairs = _migratable_pairs(discover_env_pairs(repo_root), repo_root)", "        if refusal := _migration_symlink_exit_code(destination_path, pairs, repo_root):", "            return refusal", "        source_texts = {", "            pair.local_path: pair.local_path.read_text(encoding=\"utf-8\")", "            for pair in pairs", "            if pair.local_path.exists()", "        }", "        destination_text = (", "            destination_path.read_text(encoding=\"utf-8\") if destination_path.exists() else None", "        )", "        seed_text = seed_path.read_text(encoding=\"utf-8\") if seed_path.exists() else None", "    except OSError as exc:", "        _error(str(exc))", "        return 2", "", "    parsed_sources = [_parse_env_text(text, path) for path, text in source_texts.items()]", "    destination = (", "        _parse_env_text(destination_text, destination_path)", "        if destination_text is not None", "        else None", "    )", "    seed = _parse_env_text(seed_text, seed_path) if seed_text is not None else None", "", "    # No early return on an empty ``winners``: the legacy prunes below are what a", "    # developer who already relocated their values by hand still needs, and", "    # ``winners`` is also empty when every canonical assignment is present-but-empty.", "    # Every step between here and the writes is a no-op for an empty plan.", "    winners, observations = _collect_canonical_assignments(parsed_sources, repo_root)", "", "    value_conflicts = _canonical_value_conflicts(observations)", "    plan = _plan_destination(winners, destination, seed)", "    duplicate_conflicts = _destination_duplicate_conflicts(destination, winners)", "    if value_conflicts or plan.conflicts or duplicate_conflicts:", "        _report_migration_conflicts(", "            value_conflicts,", "            plan.conflicts,", "            duplicate_conflicts,", "            observations,", "            destination_display,", "        )", "        return 1", "", "    actions: list[str] = []", "    changes: list[_MigrationFileChange] = []", "", "    # Destination first in the change list, and written first below.", "    destination_entries = destination.active_entries if destination is not None else {}", "    destination_legacy = {key for key in destination_entries if _is_legacy_queue_key(key)}", "    destination_lines = _rewrite_with_replacements(", "        destination.raw_lines if destination is not None else [],", "        plan.replacements,", "        destination_legacy,", "    )", "    _append_migrated_assignments(destination_lines, plan.additions)", "    destination_new_text = _render_env_text(destination_lines)", "    changes.append(", "        _MigrationFileChange(", "            path=destination_path,", "            original_text=destination_text,", "            new_text=destination_new_text,", "        )", "    )", "    moved_count = len(plan.additions) + len(plan.replacements)", "    if moved_count:", "        actions.append(f\"moved {moved_count} canonical queue URL(s) into {destination_display}\")", "    for key in plan.satisfied:", "        actions.append(f\"{destination_display} already carries {key} with the migrated value\")", "    if destination_legacy:", "        actions.append(", "            f\"pruned {len(destination_legacy)} legacy *_QUEUE_URL key(s) from {destination_display}\"", "        )", "", "    source_changes, source_actions = _plan_source_prunes(parsed_sources, source_texts, repo_root)", "    changes.extend(source_changes)", "    actions.extend(source_actions)", "", "    if refusal := _concurrent_edit_exit_code(", "        _snapshot_verification_targets(changes, source_texts, seed_path, seed_text), repo_root", "    ):", "        return refusal", "", "    pending = [change for change in changes if change.changed]", "", "    try:", "        for change in pending:", "            change.path.parent.mkdir(parents=True, exist_ok=True)", "            _atomic_write_text(change.path, change.new_text)", "    except OSError as exc:", "        _error(str(exc))", "        return 2", "", "    if not pending:", "        actions.append(\"nothing to write; every canonical value is already in place\")", "", "    # Never a silent success. Reached both by a developer who already ran", "    # --mirror --prune and by one whose only canonical assignments were empty --", "    # the second writes (it prunes) and so cannot be detected from ``pending``.", "    if not _carries_a_canonical_value(_parse_env_text(destination_new_text, destination_path)):", "        actions.append(", "            f\"{destination_display} carries no canonical QUEUE_URL_* value; fill it from your \"", "            \"environment's rendered ConfigMap - there is no legacy fallback after DAT-7760\"", "        )", "", "    # Not \"Applied changes\": a run can legitimately end with nothing to write.", "    print(\"Migration results:\")", "    for action in actions:", "        print(f\"  - {action}\")", "    return 0", "", "", "def _run_reflow(repo_root: Path, args: argparse.Namespace) -> int:", "    \"\"\"Reorder every selected local env file into its example's shape.", "", "    :param repo_root: Repository root used to discover and display pairs.", "    :type repo_root: Path", "    :param args: Parsed CLI arguments, for ``--file`` scoping and flag conflicts.", "    :type args: argparse.Namespace", "    :return: 1 when any pair refused to reflow, 2 on a bad invocation or IO error,", "        else 0.", "    :rtype: int", "    \"\"\"", "    if conflicts := _reflow_flag_conflicts(args):", "        _error(f\"--reflow cannot be combined with {', '.join(conflicts)}\")", "        return 2", "", "    try:", "        pairs = _resolve_selected_pairs(", "            reflowable_pairs(discover_env_pairs(repo_root), repo_root), args.file, repo_root", "        )", "    except (RuntimeError, ValueError) as exc:", "        _error(str(exc))", "        return 2", "", "    actions: list[str] = []", "    aborted = False", "    try:", "        for pair in pairs:", "            if not pair.local_path.exists():", "                local_display = _relative_to_repo(pair.local_path, repo_root)", "                actions.append(f\"skipped {local_display} (no local file; --apply creates it)\")", "                continue", "            # Refusal is read off the application, not the computed result: the", "            # concurrent-edit check only runs at write time.", "            application = apply_reflow(compute_reflow(pair), repo_root)", "            aborted = aborted or application.refused", "            actions.extend(application.messages)", "    except OSError as exc:", "        _error(str(exc))", "        return 2", "", "    if actions:", "        # Not \"Applied changes\": a run can legitimately end in an abort, a skip, or", "        # an already-in-order no-op, none of which wrote anything.", "        print(\"Reflow results:\")", "        for action in actions:", "            print(f\"  - {action}\")", "    return 1 if aborted else 0", "", "", "def _dispatch_mutating_mode(repo_root: Path, args: argparse.Namespace) -> int | None:", "    \"\"\"Run ``--reflow`` or ``--migrate-canonical`` if either was requested.", "", "    Both are dispatched ahead of the report modes so their conflict tables stay", "    reachable: were the reports handled first they would return 0 and drop the", "    mutating mode silently -- exactly the interaction", "    :func:`_reflow_flag_conflicts` and :func:`_migrate_flag_conflicts` exist to", "    reject. They are mutually exclusive, so at most one can run.", "", "    :param repo_root: Repository root used to discover and display env pairs.", "    :type repo_root: Path", "    :param args: Parsed CLI arguments.", "    :type args: argparse.Namespace", "    :return: The mode's exit code, or None when neither flag was given.", "    :rtype: int | None", "    \"\"\"", "    if args.reflow:", "        return _run_reflow(repo_root, args)", "    if args.migrate_canonical:", "        return _run_migrate_canonical(repo_root, args)", "    return None", "", "", "def main(argv: list[str] | None = None) -> int:", "    \"\"\"Run the env sync CLI.\"\"\"", "    # Force UTF-8 output so the report's non-ASCII glyphs (e.g. the \"\u2286\" in the", "    # template-superset check) don't crash with UnicodeEncodeError under a legacy", "    # console codepage \u2014 notably Windows cp1252 when this runs as a git pre-commit", "    # hook. No-op where stdout is already UTF-8 or lacks reconfigure().", "    for _stream in (sys.stdout, sys.stderr):", "        _reconfigure = getattr(_stream, \"reconfigure\", None)", "        if _reconfigure is not None:", "            # backslashreplace (not \"replace\") so any future unencodable char shows", "            # as a visible \\uNNNN escape instead of a silent \"?\" corruption.", "            _reconfigure(encoding=\"utf-8\", errors=\"backslashreplace\")", "", "    parser = build_parser()", "    args = parser.parse_args(argv)", "", "    try:", "        repo_root = _find_repo_root()", "    except RuntimeError as exc:", "        _error(str(exc))", "        return 2", "", "    early_exit = _dispatch_mutating_mode(repo_root, args)", "    if early_exit is not None:", "        return early_exit", "", "    try:", "        if args.render_sections:", "            template_path = _resolve_template_path(args.template, repo_root)", "            print(format_section_render_report(analyze_section_render(template_path)))", "            return 0", "", "        if args.compare_sections:", "            old_path, new_path = (", "                _resolve_template_path(path_arg, repo_root) for path_arg in args.compare_sections", "            )", "            compare_report = compare_section_renders(old_path, new_path)", "            print(format_section_compare_report(compare_report))", "            return 0", "    except OSError as exc:", "        _error(str(exc))", "        return 2", "", "    # The template-superset invariant compares two committed files only, so it", "    # runs standalone \u2014 no local-pair discovery, deterministic in CI.", "    if args.check_template:", "        return _run_template_superset_check(", "            repo_root, _resolve_template_path(args.template, repo_root)", "        )", "", "    try:", "        selected_pairs = _resolve_selected_pairs(", "            discover_env_pairs(repo_root), args.file, repo_root", "        )", "    except (RuntimeError, ValueError) as exc:", "        _error(str(exc))", "        return 2", "", "    reports = [analyze_pair(pair) for pair in selected_pairs]", "    print(format_reports(reports, repo_root))", "", "    # --mirror is add-missing + prune-extras in one pass; --apply stays add-only", "    # (prune only when explicitly requested). Both preserve existing local values.", "    apply_changes = args.apply or args.mirror", "    prune_extras = args.prune or args.mirror", "    applied_actions: list[str] = []", "    if apply_changes:", "        for report in reports:", "            if not report.has_drift:", "                continue", "            applied_actions.extend(apply_report(report, repo_root, prune=prune_extras))", "        if applied_actions:", "            print(\"\\nApplied changes:\")", "            for action in applied_actions:", "                print(f\"  - {action}\")", "", "    template_outcome = _superset_reports_for_check(repo_root, args)", "    if template_outcome.exit_code:", "        return template_outcome.exit_code", "", "    final_reports = [analyze_pair(pair) for pair in selected_pairs] if apply_changes else reports", "    has_pair_drift = any(report.has_drift for report in final_reports)", "    if args.check and (has_pair_drift or template_outcome.has_drift):", "        return 1", "    return 0"], "blocks": [{"start": 1, "end": 210, "label": "Imports and module setup"}, {"start": 211, "end": 221, "label": "def _is_canonical_queue_key"}, {"start": 222, "end": 236, "label": "def _is_legacy_queue_key"}, {"start": 237, "end": 278, "label": "def _dotenv_value_is_empty"}, {"start": 279, "end": 291, "label": "def env_sync_key_is_ignored"}, {"start": 292, "end": 304, "label": "class EnvLine"}, {"start": 305, "end": 311, "label": "class ParsedEnvFile"}, {"start": 312, "end": 316, "label": "ParsedEnvFile.raw_lines"}, {"start": 317, "end": 323, "label": "ParsedEnvFile.active_entries"}, {"start": 324, "end": 332, "label": "ParsedEnvFile.commented_entries"}, {"start": 333, "end": 341, "label": "ParsedEnvFile.all_entries"}, {"start": 342, "end": 347, "label": "ParsedEnvFile.active_key_order"}, {"start": 348, "end": 355, "label": "class EnvPair"}, {"start": 356, "end": 366, "label": "class PairReport"}, {"start": 367, "end": 377, "label": "PairReport.has_drift"}, {"start": 378, "end": 386, "label": "class TemplateSupersetReport"}, {"start": 387, "end": 392, "label": "TemplateSupersetReport.has_drift"}, {"start": 393, "end": 402, "label": "class ExampleSectionMisplacement"}, {"start": 403, "end": 409, "label": "class ExampleSectionAlignmentReport"}, {"start": 410, "end": 415, "label": "ExampleSectionAlignmentReport.has_drift"}, {"start": 416, "end": 431, "label": "class ReflowResult"}, {"start": 432, "end": 439, "label": "class ReleaseRender"}, {"start": 440, "end": 447, "label": "class SectionRenderReport"}, {"start": 448, "end": 456, "label": "class ReleaseSectionDiff"}, {"start": 457, "end": 465, "label": "class SectionCompareReport"}, {"start": 466, "end": 474, "label": "class SectionValidationViolation"}, {"start": 475, "end": 481, "label": "class SectionValidationReport"}, {"start": 482, "end": 487, "label": "SectionValidationReport.has_violations"}, {"start": 488, "end": 491, "label": "def _error"}, {"start": 492, "end": 495, "label": "def _warn"}, {"start": 496, "end": 504, "label": "def _find_repo_root"}, {"start": 505, "end": 521, "label": "def _parse_line"}, {"start": 522, "end": 533, "label": "def _section_marker_name"}, {"start": 534, "end": 550, "label": "def _canonical_section"}, {"start": 551, "end": 567, "label": "def _expected_example_path"}, {"start": 568, "end": 582, "label": "def _migratable_example_paths"}, {"start": 583, "end": 598, "label": "def _is_migratable_pair"}, {"start": 599, "end": 603, "label": "def parse_env_file"}, {"start": 604, "end": 630, "label": "def _parse_env_text"}, {"start": 631, "end": 644, "label": "def release_sections"}, {"start": 645, "end": 660, "label": "def rendered_keys_by_release"}, {"start": 661, "end": 672, "label": "def analyze_section_render"}, {"start": 673, "end": 692, "label": "def compare_section_renders"}, {"start": 693, "end": 801, "label": "def analyze_section_validation"}, {"start": 802, "end": 817, "label": "def discover_env_pairs"}, {"start": 818, "end": 868, "label": "def analyze_pair"}, {"start": 869, "end": 877, "label": "def _template_relevant_keys"}, {"start": 878, "end": 917, "label": "def analyze_template_superset"}, {"start": 918, "end": 1012, "label": "def resolve_section_example_map"}, {"start": 1013, "end": 1035, "label": "def _derive_template_scope"}, {"start": 1036, "end": 1068, "label": "def _template_key_sections"}, {"start": 1069, "end": 1128, "label": "def analyze_example_section_alignment"}, {"start": 1129, "end": 1136, "label": "def _relative_to_repo"}, {"start": 1137, "end": 1169, "label": "def _resolve_selected_pairs"}, {"start": 1170, "end": 1191, "label": "def _migration_hint_applies"}, {"start": 1192, "end": 1233, "label": "def _render_report"}, {"start": 1234, "end": 1243, "label": "def format_reports"}, {"start": 1244, "end": 1265, "label": "def _render_template_superset_report"}, {"start": 1266, "end": 1277, "label": "def format_template_superset_reports"}, {"start": 1278, "end": 1307, "label": "def format_example_coverage_violations"}, {"start": 1308, "end": 1342, "label": "def format_example_section_alignment_report"}, {"start": 1343, "end": 1353, "label": "def format_section_render_report"}, {"start": 1354, "end": 1371, "label": "def format_section_compare_report"}, {"start": 1372, "end": 1386, "label": "def format_section_validation_report"}, {"start": 1387, "end": 1392, "label": "def _resolve_template_path"}, {"start": 1393, "end": 1420, "label": "def _append_missing_entries"}, {"start": 1421, "end": 1438, "label": "def _prune_extra_keys"}, {"start": 1439, "end": 1453, "label": "def _strip_ignored_assignment_lines"}, {"start": 1454, "end": 1499, "label": "def apply_report"}, {"start": 1500, "end": 1519, "label": "def reflowable_pairs"}, {"start": 1520, "end": 1543, "label": "def _assignment_multiset"}, {"start": 1544, "end": 1573, "label": "def _reflow_abort_reason"}, {"start": 1574, "end": 1579, "label": "def _duplicate_active_keys"}, {"start": 1580, "end": 1597, "label": "def _unparsed_line_numbers"}, {"start": 1598, "end": 1611, "label": "def _quoted_value_span"}, {"start": 1612, "end": 1654, "label": "def _unterminated_quote_line_numbers"}, {"start": 1655, "end": 1685, "label": "def _unparsed_line_abort_reason"}, {"start": 1686, "end": 1707, "label": "def _interpolating_active_keys"}, {"start": 1708, "end": 1748, "label": "def _reflow_refusal_reason"}, {"start": 1749, "end": 1819, "label": "def _reflow_lines"}, {"start": 1820, "end": 1900, "label": "def compute_reflow"}, {"start": 1901, "end": 1943, "label": "def _atomic_write_text"}, {"start": 1944, "end": 1957, "label": "class ReflowApplication"}, {"start": 1958, "end": 1998, "label": "def apply_reflow"}, {"start": 1999, "end": 2101, "label": "def build_parser"}, {"start": 2102, "end": 2117, "label": "class _SupersetScan"}, {"start": 2118, "end": 2168, "label": "def _scan_template_superset"}, {"start": 2169, "end": 2183, "label": "class _TemplateCheckOutcome"}, {"start": 2184, "end": 2193, "label": "_TemplateCheckOutcome.has_drift"}, {"start": 2194, "end": 2249, "label": "def _superset_reports_for_check"}, {"start": 2250, "end": 2299, "label": "def _run_template_superset_check"}, {"start": 2300, "end": 2327, "label": "def _reflow_flag_conflicts"}, {"start": 2328, "end": 2335, "label": "class _CanonicalObservation"}, {"start": 2336, "end": 2348, "label": "class _MigrationFileChange"}, {"start": 2349, "end": 2354, "label": "_MigrationFileChange.changed"}, {"start": 2355, "end": 2364, "label": "class _DestinationPlan"}, {"start": 2365, "end": 2376, "label": "def _render_env_text"}, {"start": 2377, "end": 2405, "label": "def _migratable_pairs"}, {"start": 2406, "end": 2448, "label": "def _collect_canonical_assignments"}, {"start": 2449, "end": 2469, "label": "def _canonical_value_conflicts"}, {"start": 2470, "end": 2539, "label": "def _plan_destination"}, {"start": 2540, "end": 2558, "label": "def _carries_a_canonical_value"}, {"start": 2559, "end": 2602, "label": "def _destination_duplicate_conflicts"}, {"start": 2603, "end": 2640, "label": "def _rewrite_with_replacements"}, {"start": 2641, "end": 2661, "label": "def _append_migrated_assignments"}, {"start": 2662, "end": 2693, "label": "def _migrate_flag_conflicts"}, {"start": 2694, "end": 2744, "label": "def _report_migration_conflicts"}, {"start": 2745, "end": 2788, "label": "def _plan_source_prunes"}, {"start": 2789, "end": 2806, "label": "def _relative_link_display"}, {"start": 2807, "end": 2841, "label": "def _migration_symlink_exit_code"}, {"start": 2842, "end": 2888, "label": "def _snapshot_verification_targets"}, {"start": 2889, "end": 2930, "label": "def _concurrent_edit_exit_code"}, {"start": 2931, "end": 3073, "label": "def _run_migrate_canonical"}, {"start": 3074, "end": 3122, "label": "def _run_reflow"}, {"start": 3123, "end": 3145, "label": "def _dispatch_mutating_mode"}, {"start": 3146, "end": 3230, "label": "def main"}], "lineCount": 3230, "sha256": "7e8ca8ee3e7401f71484b86d0e3a963266e5e07387982b692ede440e36b448cc", "endsWithNewline": true});
